insert into private.study_guides (guide, chunks, sha256) values ('study_guide_fin101', 32, '210e2818c5459660c9de102293306e8f08e2007dbe7bc089bbf473479a47a426');
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin101', 1, $study_guide${"guide":"study_guide_fin101","code":"FIN101","courseId":"203d7e61-c829-5419-a664-5a478e05a8a6","actor":"00000000-0000-4000-8000-000000000045","overview":{"itemId":"f1def905-4500-5685-805b-a989083ec232","create":true,"after":{"title":"Introduction to Finance","body":"Every topic is examinable.","outcomes":["Explain the meaning and scope of finance, the finance function (investment, financing and dividend decisions) and financial management as a tool for planning and control.","Compare profit maximisation and wealth maximisation, and explain stakeholders, the agency problem and agency costs.","Distinguish risk from uncertainty, name the types of risk, and measure risk with expected value, standard deviation and the coefficient of variation.","Calculate simple and compound interest, present and terminal values, annuities and perpetuities, and work with arithmetic and geometric progressions.","Calculate and interpret liquidity, activity, profitability, gearing and market ratios, and state the limits of ratio analysis.","Describe the money and capital markets, primary and secondary markets, the stock market, financial institutions and the sources of finance.","Compare the forms of business firm and explain limited liability."],"assessment":["The exam is objective (CBT), with some theory questions. Expect definitions, lists, calculations and Nigerian institutions.","Calculations come from Topics 3, 4 and 5. Practise the formulas until you can do them quickly."]}},"retire":[],"notes":[{"kind":"note","itemId":"4ad8d8de-4062-5819-ae27-9f8b499aaccf","sourceKey":"guide-topic:1","position":1,"payload":{"title":"Overview of Finance","body":"The meaning and scope of finance; how finance differs from economics and accounting; the branches of finance; the four finance decisions and their other names; the financial manager's role; financial management as a tool for planning and control; the limited liability company and the risks of finance.","noteType":"guide_topic","number":1,"mustKnow":[{"text":"The meaning and scope of finance; how finance differs from economics and accounting; the branches of finance; the four finance decisions and their other names; the financial manager's role; financial management as a tool for planning and control; the limited liability company and the risks of finance."}],"lessons":[{"number":"1.1","title":"Meaning and scope of finance","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Finance:","bold":true},{"text":" the management of money and the process of acquiring the needed funds to achieve a set objective. Put more shortly, finance is the "},{"text":"management of money and money claims","bold":true},{"text":": finance is money, and availability of finance is availability of money."}]},{"text":[{"text":"Finance deals with the "},{"text":"inflows (sources)","bold":true},{"text":" and "},{"text":"outflows (uses)","bold":true},{"text":" of money (funds) within the firm. It serves as a "},{"text":"link","bold":true},{"text":" that makes business interrelationships possible."}]},{"text":[{"text":"Activities of finance (6):","bold":true},{"text":" saving, borrowing, lending, investing, budgeting, forecasting."}]},{"text":[{"text":"Money is important to "},{"text":"individuals","bold":true},{"text":", "},{"text":"businesses","bold":true},{"text":" and "},{"text":"government","bold":true},{"text":", to finance their activities and achieve their targets."}]},{"text":[{"text":"Finance functions of the firm:","bold":true},{"text":" raising capital funds, using them to generate returns, and paying returns to the suppliers of funds (interest to lenders, dividends to shareholders)."}]}]},{"type":"paragraph","text":[{"text":"Importance (characteristics) of finance in a business firm (4):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Finance "},{"text":"enhances business growth","bold":true},{"text":"."}]},{"text":[{"text":"Finance serves as a "},{"text":"standard (stand) upon which business performance can be measured","bold":true},{"text":"."}]},{"text":[{"text":"Finance "},{"text":"links all other activities together","bold":true},{"text":": marketing, purchasing, production, selling and distribution."}]},{"text":[{"text":"Finance is a "},{"text":"new discipline which has grown rapidly","bold":true},{"text":"."}]}]},{"type":"table","header":[[],[{"text":"Finance"}],[{"text":"Economics"}],[{"text":"Accounting"}]],"rows":[[[{"text":"Main concern"}],[{"text":"Managing money: raising, investing, returning funds"}],[{"text":"How society allocates scarce resources (micro and macro)"}],[{"text":"Recording, classifying and reporting transactions"}]],[[{"text":"Basis"}],[{"text":"Cash flows, time value of money, risk and return"}],[{"text":"Theory of demand, supply, prices, national income"}],[{"text":"Accrual basis (income when earned, expense when incurred)"}]],[[{"text":"Output"}],[{"text":"Decisions (invest, finance, pay dividends)"}],[{"text":"Theories and policies"}],[{"text":"Financial statements"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Finance is primarily concerned with "},{"text":"managing monetary resources and investments","bold":true},{"text":". If an option says workforce productivity, promoting goods, organisational hierarchy, product pricing or employee welfare, it belongs to human resources, marketing or management, not finance."}]},{"text":[{"text":"Studying finance helps you "},{"text":"optimise resource allocation decisions","bold":true},{"text":": putting scarce funds where they earn the best return for the risk taken. It also "},{"text":"enables informed strategic choices","bold":true},{"text":". Options claiming finance \"eliminates planning\", \"neglects risk\" or \"centres solely on profit\" are traps: finance needs planning, treats risk as central, and looks beyond profit to value."}]},{"text":[{"text":"The field of finance "},{"text":"includes investments and financial $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin101', 2, $study_guide$market dynamics","bold":true},{"text":". Watch for words like \"exclusively\", \"solely\" and \"purely\" (ledger keeping, promotion, manufacturing); they mark wrong options."}]},{"text":[{"text":"Finance and economics:","bold":true},{"text":" finance borrows from economics. Microeconomics gives the firm marginal analysis (go ahead only if extra benefit exceeds extra cost); macroeconomics gives the setting: interest rates, inflation and CBN monetary policy all shape a Nigerian firm's cost of funds."}]},{"text":[{"text":"Finance and accounting:","bold":true},{"text":" the accountant records that a sale of ₦2,000,000 on credit is revenue today; the finance person asks when the ₦2,000,000 cash will actually arrive, because a firm can show profit and still run out of cash. Accounting provides the data; finance uses it to decide."}]}]}]},{"number":"1.2","title":"Branches of finance and financial management","mustKnow":[{"type":"paragraph","text":[{"text":"Three categories of finance:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Personal finance:","bold":true},{"text":" how an individual or household handles income, savings, spending, borrowing and investments (an individual's financial assets)."}]},{"text":[{"text":"Business (corporate) finance:","bold":true},{"text":" how a firm raises and uses funds; overseeing a firm's financial operations: raising capital, choosing investments, paying dividends."}]},{"text":[{"text":"Public finance:","bold":true},{"text":" how government raises revenue (taxes, borrowing) and spends it; administering public sector budgets and tax policy."}]}]},{"type":"paragraph","text":[{"text":"A fourth branch is often added:"}]},{"type":"list","ordered":true,"start":4,"items":[{"text":[{"text":"International finance:","bold":true},{"text":" financial dealings across borders: exchange rates, foreign trade and investment, global trade deals."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Financial management:","bold":true},{"text":" the management of the finances of individuals, business or government in order to achieve set objectives."}]},{"text":[{"text":"The focus of this course is "},{"text":"business (corporate) finance","bold":true},{"text":", so financial management is "},{"text":"the study of how firms make their investment and financing decisions","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Match the description to the branch. \"Managing individual savings accounts\" = personal. \"Directing corporate cash flows\" or \"overseeing a firm's financial operations\" = corporate. \"Administering public sector budgets\" or \"administering tax policies\" = public. \"Facilitating global trade deals\" = international."}]},{"text":[{"text":"Nigerian examples: a student saving pocket money in a bank account and buying treasury bills is personal finance; Dangote Cement raising funds on the Nigerian Exchange (NGX) is corporate finance; the Federal Government's annual budget and federal tax collection are public finance; a Nigerian importer paying a Chinese supplier in yuan is international finance."}]},{"text":[{"text":"Corporate finance for business funding","bold":true},{"text":" is a key area of finance; product design, staff development and consumer behaviour are not."}]}]}]},{"number":"1.3","title":"The finance function: the four decisions","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Finance functions:","bold":true},{"text":" practices and activities focused on managing a business's financial resources to generate profits. They cover "},{"text":"investment, dividend, financing and liquidity","bold":true},{"text":" decisions, among others. They keep the firm financially stable and support growth and profitability."}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Investment (capital budgeting) decision:","bold":true},{"text":" the allocation of the firm's capital funds to investment proposals that yield future benefits meeting the expectations of all investors, i.e. how much to invest in physical assets or financial assets (securities). Also called the "},{"text":"capital budgeting decision","bold":true},{"text":". Planning capital expenditure is an investment decision."}]},{"text":[{"text":"Financing decision:","bold":true},{"text":" determining the "},{"text":"best financing mix (capital structure)","bold":true},{"text":": sourcing funds at the "},{"text":"cheapest cost","bold":true},{"text":", with the "},{"text":"most favourable tax","bold":true},{"text":", at the "},{"text":"best mix","bold":true},{"text":", to "},{"text":"maximise the market price per share (MPS)","bold":true},{"text":". Also called the "},{"text":"capital mix decision","bold":true},{"text":"."}]},{"text":[{"text":"Dividend decision:","bold":true},{"text":" determining the proportion of earnings to "},{"text":"pay out as dividend","bold":true},{"text":" or "},{"text":"retain","bold":true},{"text":" in the firm, bearing in mind the need to maximise shareholders' (owners') wealth. Also called the "},{"text":"profit allocation decision","bold":true},{"text":"."}]},{"text":[{"text":"Liquidity decision:","bold":true},{"text":" the "},{"text":"working capital decision","bold":true},{"text":": managing current assets and current liabilities (cash, inventory, receivables, payables) so the firm can pay its way day to day."}]}]},{"type":"paragraph","text":[{"text":"Other finance functions:","bold":true},{"text":" managing cash flows, risk management, financial planning, financial analysis, financial control."}]},{"type":"paragraph","text":[{"text":"Key terms:","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Capital budgeting:","bold":true},{"text":" making "},{"text":"long-term investment decisions","bold":true},{"text":" (new machinery, a new factory) that bring returns over many years."}]},{"text":[{"text":"Capital budgetin$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin101', 3, $study_guide$g techniques:","bold":true},{"text":" net present value (NPV), "},{"text":"internal rate of return (IRR)","bold":true},{"text":", payback period, accounting rate of return (ARR), profitability index."}]},{"text":[{"text":"Internal rate of return (IRR):","bold":true},{"text":" the discount rate at which a project's NPV equals zero. Accept the project if IRR is greater than the cost of capital."}]},{"text":[{"text":"Cost of capital:","bold":true},{"text":" the "},{"text":"cost of obtaining funds","bold":true},{"text":": the return a firm must pay suppliers of funds (interest to lenders, the return shareholders expect)."}]},{"text":[{"text":"Dividend:","bold":true},{"text":" a "},{"text":"portion of a company's profit distributed to shareholders","bold":true},{"text":"."}]},{"text":[{"text":"Retained earnings","bold":true},{"text":" = profit after tax − dividends paid."}]}]},{"type":"table","header":[[{"text":"Decision"}],[{"text":"Other name"}],[{"text":"Question it answers"}]],"rows":[[[{"text":"Investment"}],[{"text":"Capital budgeting"}],[{"text":"Where should funds go?"}]],[[{"text":"Financing"}],[{"text":"Capital mix (capital structure)"}],[{"text":"Where should funds come from?"}]],[[{"text":"Dividend"}],[{"text":"Profit allocation"}],[{"text":"How much profit to pay out or keep?"}]],[[{"text":"Liquidity"}],[{"text":"Working capital"}],[{"text":"Can we meet short-term obligations?"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap on names:","bold":true},{"text":" capital mix = financing; profit allocation = dividend; capital budgeting = investment. \"Capital project decision\" and \"capital rating decision\" are not the standard names. "},{"text":"Capital rationing","bold":true},{"text":" is only a special case within the investment decision (when funds are too few for all good projects), so it is not another name for any of the decisions."}]},{"text":[{"text":"Not finance functions:","bold":true},{"text":" "},{"text":"financial forensics","bold":true},{"text":" (investigating fraud, a specialist audit and legal activity) and an "},{"text":"acquisition decision","bold":true},{"text":" (a specific strategic choice). The three major managerial finance decisions of a limited liability company are investment, financing and dividend."}]},{"text":[{"text":"Ratios such as debt-to-equity and current ratio, and the cash conversion cycle, are "},{"text":"not","bold":true},{"text":" capital budgeting techniques. Managing daily expenses is working capital, not capital budgeting."}]}]},{"type":"paragraph","text":[{"text":"Worked example (dividend decision):","bold":true},{"text":" Ade Foods plc earns profit after tax of ₦50,000,000 and decides to pay out 40% as dividend."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Dividend paid = 40% × ₦50,000,000 = ₦20,000,000."}]},{"text":[{"text":"Retained = ₦50,000,000 − ₦20,000,000 = ₦30,000,000 (60%), available to finance new investment."}]}]},{"type":"paragraph","text":[{"text":"Worked example (cost of capital and IRR):","bold":true},{"text":" A project costs ₦1,000,000 today and returns a single ₦1,210,000 in two years. The firm's cost of capital is 8%."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"NPV at 8% = 1,210,000 ÷ (1.08)^2 − 1,000,000 = 1,210,000 ÷ 1.1664 − 1,000,000 = ₦37,380 (to the nearest naira). Positive, so accept."}]},{"text":[{"text":"IRR: find r where 1,000,000 × (1 + r)^2 = 1,210,000. (1 + r)^2 = 1.21, so 1 + r = 1.1 and IRR = 10%."}]},{"text":[{"text":"IRR (10%) > cost of capital (8%), so accept. Both methods agree."}]}]}]},{"number":"1.4","title":"The financial manager; planning and control","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Financial manager:","bold":true},{"text":" the finance employee who "},{"text":"manages the funds of an organisation","bold":true},{"text":" and undertakes financial management roles. The primary role is to "},{"text":"manage the firm's finances and maximise its value","bold":true},{"text":" (shareholders' wealth)."}]}]},{"type":"paragraph","text":[{"text":"Roles of the financial manager:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Estimating the funds needed (financial planning and forecasting)."}]},{"text":[{"text":"Raising funds from the best sources at the lowest cost (financing decision)."}]},{"text":[{"text":"Evaluating investment opportunities","bold":true},{"text":" and allocating funds (investment decision)."}]},{"text":[{"text":"Recommending dividend and retention policy (dividend decision)."}]},{"text":[{"text":"Managing working capital and cash flows (liquidity decision)."}]},{"text":[{"text":"Managing financial risk."}]},{"text":[{"text":"Financial analysis, reporting and control."}]},{"text":[{"text":"Dealing with banks, investors and the capital market."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Financial planning:","bold":true},{"text":" deciding in advance the firm's financial goals and how to reach them. Components: "},{"text":"defining monetary (financial) objectives","bold":true},{"text":", estimating funds needed, choosing sources, budgeting, forecasting."}]},{"text":[{"text":"Financial control:","bold":true},{"text":" checking that actual results match the plan and correcting deviations."}]}]},{"type":"paragraph","text":[{"text":"Financial management as a tool for planning and control:","bold":true},{"text":" budgets turn plans into figures; actual results are measured and compared with budget; variances are investigated; corrective action is taken. This cycle is "},{"text":"plan → act → measure → compare → correct","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Principles for planning and control:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Clear objectives:","bold":true},{"text":" plans start from defined financial goals."}]},{"text":[{"text":"Realistic forecasting:","bold"$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin101', 4, $study_guide$:true},{"text":" based on reliable information."}]},{"text":[{"text":"Flexibility:","bold":true},{"text":" plans can be adjusted when conditions change."}]},{"text":[{"text":"Participation:","bold":true},{"text":" those who carry out the plan help set it."}]},{"text":[{"text":"Responsibility:","bold":true},{"text":" each budget item is assigned to a named manager."}]},{"text":[{"text":"Timely measurement and feedback:","bold":true},{"text":" results are reported quickly enough to act on."}]},{"text":[{"text":"Management by exception:","bold":true},{"text":" attention goes to significant variances."}]},{"text":[{"text":"Cost-benefit:","bold":true},{"text":" controls should cost less than the benefit they bring."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A "},{"text":"financial analyst","bold":true},{"text":" studies and reports on financial data; a "},{"text":"financial planner","bold":true},{"text":" usually advises individuals; a "},{"text":"financial controller","bold":true},{"text":" mainly oversees accounting and reporting. The one who manages the organisation's funds and makes the finance decisions is the "},{"text":"financial manager","bold":true},{"text":"."}]},{"text":[{"text":"Recruiting staff, crafting product prototypes, analysing market demographics, ensuring customer satisfaction and preparing legal documents are not the financial manager's job."}]},{"text":[{"text":"Worked example (control):","bold":true},{"text":" A firm budgets ₦8,000,000 for transport in a year but spends ₦9,200,000. Variance = ₦9,200,000 − ₦8,000,000 = ₦1,200,000 adverse, i.e. 1,200,000 ÷ 8,000,000 × 100 = 15% over budget. Under management by exception, the manager investigates this large overspend (perhaps a fuel price rise) and corrects it."}]}]}]},{"number":"1.5","title":"The limited liability company and the nature and risks of finance","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Limited liability company:","bold":true},{"text":" a business registered (in Nigeria with the Corporate Affairs Commission, CAC) as a separate legal person, owned by shareholders whose liability is "},{"text":"limited to the amount unpaid on their shares","bold":true},{"text":"."}]},{"text":[{"text":"Features:","bold":true},{"text":" separate legal entity; limited liability; perpetual succession (continues when owners die or sell); transferable shares; "},{"text":"ownership separate from control","bold":true},{"text":" (shareholders own, directors and managers run it); can raise large funds by issuing shares and debentures."}]},{"text":[{"text":"Private (Ltd)","bold":true},{"text":" cannot invite the public to buy its shares; "},{"text":"public (plc)","bold":true},{"text":" can, and may list on the NGX under SEC regulation."}]}]},{"type":"paragraph","text":[{"text":"Nature of finance:","bold":true},{"text":" finance is about money over "},{"text":"time","bold":true},{"text":" and under "},{"text":"risk","bold":true},{"text":". A naira today is worth more than a naira later, and future returns are uncertain, so every finance decision weighs "},{"text":"risk against return","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Risks of finance:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Business risk:","bold":true},{"text":" variability of operating profit from the nature of the business."}]},{"text":[{"text":"Financial risk:","bold":true},{"text":" extra risk from using debt; interest must be paid even in bad years."}]},{"text":[{"text":"Liquidity risk:","bold":true},{"text":" inability to meet short-term obligations."}]},{"text":[{"text":"Interest-rate and inflation risk:","bold":true},{"text":" rising rates raise the cost of funds; inflation erodes the value of returns."}]},{"text":[{"text":"Credit (default) risk:","bold":true},{"text":" customers or borrowers fail to pay."}]},{"text":[{"text":"Exchange-rate risk:","bold":true},{"text":" naira movements change the value of foreign payments and receipts."}]}]},{"type":"paragraph","text":[{"text":"Objectives of business firms (studied fully in Topic 2):","bold":true},{"text":" (A) profit maximisation (increased revenue with lower cost); (B) wealth maximisation (shareholders' wealth); (C) satisfaction (satisfied customers stay loyal, recommend and repeat purchase); (D) social responsibility; (E) increase in market share (to be market leader). Others: growth, improved productivity, diversification, technical leadership, a contented workforce, highest quality service to customers."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Limited liability is why people will buy shares in a company they do not run: the most a shareholder can lose is what he paid (or still owes) for his shares. If Kunle buys 10,000 shares at ₦5 fully paid (₦50,000) and the company fails owing ₦100,000,000, Kunle loses at most ₦50,000; creditors cannot take his house."}]},{"text":[{"text":"Separation of ownership and control means managers may not always act for shareholders; the financial manager's task of maximising value is meant to align the firm's decisions with the owners' wealth."}]},{"text":[{"text":"Worked example (financial risk):","bold":true},{"text":" Two firms each earn operating profit of ₦10,000,000. Firm A has no debt; Firm B pays interest of ₦6,000,000. If operating profit falls by 40% to ₦6,000,000, Firm A still has ₦6,000,000 before tax, while Firm B has ₦6,000,000 − ₦6,000,000 = ₦0. Debt magnifies the effect of a fall; that is financial risk."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Finance = management of money and money claims; inflows (sources) and outflows (uses) of funds."}]},{"text":[{"text":"Activities: saving, borrowing, lending, investing, budgeting, forecasting."}]},{"text":[{"text":"Importance: enhances growth, standard for measuring performance, links all activities, a new and fast-growing disciplin$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin101', 5, $study_guide$e."}]},{"text":[{"text":"Branches: personal, business (corporate), public, plus international."}]},{"text":[{"text":"Financial management = how firms make investment and financing decisions."}]},{"text":[{"text":"Four decisions: investment (capital budgeting), financing (capital mix), dividend (profit allocation), liquidity (working capital)."}]},{"text":[{"text":"Cost of capital = cost of obtaining funds; IRR = rate where NPV = 0, a capital budgeting technique; dividend = profit paid to shareholders."}]},{"text":[{"text":"Financial manager manages the organisation's funds to maximise value; financial forensics and acquisition decisions are not core finance functions."}]},{"text":[{"text":"Planning and control: plan, act, measure, compare, correct."}]},{"text":[{"text":"Limited liability company: separate legal entity, liability limited to unpaid shares, ownership separate from control."}]}]}],"theory":{"itemId":"b463c843-3c57-55e1-97b1-e602e2108f20","question":[{"type":"paragraph","text":[{"text":"Zenith Agro plc earns profit after tax of ₦80,000,000 and pays a dividend of 25%. (a) How much is retained? (b) Which finance decision is this, and what is its other name?"}]}]},"practice":[{"topic":"Overview of Finance","named":false}]}},{"kind":"note","itemId":"1f2e020f-ff48-513f-860a-5823772973b2","sourceKey":"guide-topic:2","position":2,"payload":{"title":"Objective of a Firm","body":"Profit maximisation and its criticisms; shareholders' wealth maximisation, NPV and why it is superior; the other objectives (satisfaction, social responsibility, survival, market share, growth and the rest); stakeholders; the agency problem and agency costs; the objectives of financial decisions.","noteType":"guide_topic","number":2,"mustKnow":[{"text":"Profit maximisation and its criticisms; shareholders' wealth maximisation, NPV and why it is superior; the other objectives (satisfaction, social responsibility, survival, market share, growth and the rest); stakeholders; the agency problem and agency costs; the objectives of financial decisions."}],"lessons":[{"number":"2.1","title":"Profit maximisation objective","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Profit maximisation:","bold":true},{"text":" the firm aims to make as much profit as possible by "},{"text":"maximising revenue","bold":true},{"text":" from the sale of its output while "},{"text":"minimising the cost","bold":true},{"text":" of producing that output (increased revenue with lower cost)."}]},{"text":[{"text":"It is regarded as the "},{"text":"primary (traditional) objective","bold":true},{"text":" of a firm. It was developed in the "},{"text":"early 19th century","bold":true},{"text":", when firms were mainly "},{"text":"sole proprietorships","bold":true},{"text":" and "},{"text":"self-financing","bold":true},{"text":" (owner and manager were the same person)."}]},{"text":[{"text":"Merit:","bold":true},{"text":" it is "},{"text":"very easy to measure","bold":true},{"text":". It requires the firm to be efficient in its use of resources and focuses its effort on making money."}]},{"text":[{"text":"Profit maximisation is the objective that has been "},{"text":"attacked by all and sundry","bold":true},{"text":", for these "},{"text":"5 reasons","bold":true},{"text":":"}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"It does "},{"text":"not recognise the time value of money","bold":true},{"text":" (₦1 received today is treated the same as ₦1 received in five years)."}]},{"text":[{"text":"It does "},{"text":"not consider risk or uncertainty","bold":true},{"text":" of future earnings."}]},{"text":[{"text":"Profit has no clear definition:","bold":true},{"text":" it does not state whether it means profit before tax or after tax, short-term or long-term profit."}]},{"text":[{"text":"It does "},{"text":"not consider the quality aspect","bold":true},{"text":" of the firm's future activities."}]},{"text":[{"text":"It does "},{"text":"not give all participants or interest groups","bold":true},{"text":" (customers, creditors, shareholders, government, employees, competitors) a "},{"text":"satisfactory return","bold":true},{"text":" for their inputs or efforts."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Because it ignores timing, profit maximisation "},{"text":"focuses on immediate (short-term) financial gains","bold":true},{"text":". A manager chasing this year's profit may cut anything whose benefit comes later."}]},{"text":[{"text":"What conflicts with profit maximisation?","bold":true},{"text":" Spending that raises cost today but pays off only later, such as "},{"text":"funding staff skill development (training)","bold":true},{"text":", research or community projects. By contrast, streamlining production, trimming operating expenses and broadening market reach all "},{"text":"support","bold":true},{"text":" profit maximisation, because they cut cost or raise sales."}]},{"text":[{"text":"Exam cue words: \""},{"text":"primary","bold":true},{"text":" objective of a business firm\" or \""},{"text":"main objective of a business","bold":true},{"text":"\" with profit among the options → "},{"text":"maximise profits for its owners","bold":true},{"text":". Contrast with Lesson 2.2: \"main goal of "},{"text":"financial management","bold":true},{"text":"\" → "},{"text":"maximise shareholder wealth","bold":true},{"text":"."}]},{"text":[{"text":"Trap: profit maximisation is easy to "},{"text":"measure","bold":true},{"text":"; its weakness is not measurement but timing, risk, vagueness, quality and fairness to other groups."}]}]}]},{"number":"2.2","title":"Shareholders' wealth maximisation objective","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Shareholders' wealth maximisation (SWM):","bold":true},{"text":" widely accepted as the "},{"text":"best means of maximising the economic welfare of shareholders","bold":true},{"text":" of a firm. It is the "},{"tex$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin101', 6, $study_guide$t":"main goal of financial management","bold":true},{"text":": to "},{"text":"maximise shareholder wealth over time","bold":true},{"text":"."}]},{"text":[{"text":"It simply means "},{"text":"maximising the Net Present Value (NPV)","bold":true},{"text":" of a course of action."}]},{"text":[{"text":"NPV:","bold":true},{"text":" the difference between the "},{"text":"present value of the benefits","bold":true},{"text":" of an action and the "},{"text":"initial investment","bold":true},{"text":" required to achieve those benefits."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"NPV = PV of future cash inflows − initial investment"}]},{"text":[{"text":"PV of a cash flow C received in year n = C / (1 + r)^n, where r is the required rate of return."}]},{"text":[{"text":"Accept actions with NPV > 0; they add to shareholders' wealth."}]}]}]},{"text":[{"text":"Shareholder wealth is represented by the market price per share","bold":true},{"text":" of the firm's ordinary (common) shares. So the financial objective of a firm is to "},{"text":"maximise the market value of its shares","bold":true},{"text":"."}]},{"text":[{"text":"Share value is set by the price at which the shares trade in the market place, such as the "},{"text":"Nigerian Exchange (NGX)","bold":true},{"text":" in Lagos."}]},{"text":[{"text":"The market price reflects the firm's managerial decisions: "},{"text":"investment, financing and dividend decisions","bold":true},{"text":"."}]},{"text":[{"text":"Maximising shareholder wealth means "},{"text":"enhancing share value and payouts","bold":true},{"text":" (rising share price plus dividends). It aligns with "},{"text":"building enduring (long-term) value","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Superiority of SWM over profit maximisation (8 points):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"It "},{"text":"recognises the time value of money","bold":true},{"text":"."}]},{"text":[{"text":"It "},{"text":"considers the effect of risk","bold":true},{"text":" or uncertainty of future earnings."}]},{"text":[{"text":"It "},{"text":"balances short-term and long-term profit","bold":true},{"text":" in a way profit maximisation cannot."}]},{"text":[{"text":"It "},{"text":"considers the quality aspect","bold":true},{"text":" of the firm's future activities."}]},{"text":[{"text":"It gives "},{"text":"all participants or interest groups","bold":true},{"text":" a satisfactory return for their inputs or efforts."}]},{"text":[{"text":"It is a "},{"text":"yardstick for measuring the overall performance","bold":true},{"text":" of a firm; share performance on the stock market has a direct relationship with shareholder wealth."}]},{"text":[{"text":"It is the "},{"text":"best factor in wooing further investors","bold":true},{"text":" into a firm."}]},{"text":[{"text":"It provides "},{"text":"appropriate and operationally feasible criteria","bold":true},{"text":" for choosing between alternative courses of action."}]}]},{"type":"table","header":[[{"text":"Point"}],[{"text":"Profit maximisation"}],[{"text":"Shareholders' wealth maximisation"}]],"rows":[[[{"text":"Time value of money"}],[{"text":"Ignored"}],[{"text":"Recognised (discounting, NPV)"}]],[[{"text":"Risk"}],[{"text":"Ignored"}],[{"text":"Considered"}]],[[{"text":"Time horizon"}],[{"text":"Short term, immediate gains"}],[{"text":"Long term, enduring value"}]],[[{"text":"Definition"}],[{"text":"Vague (before/after tax? short/long?)"}],[{"text":"Clear: market price per share"}]],[[{"text":"Shareholders' view"}],[{"text":"Not reflected"}],[{"text":"Reflected in the share price"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Worked example (why timing matters).","bold":true},{"text":" Discount rate 10%. Each project costs ₦1,000,000 now."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Project A pays ₦600,000 at the end of year 1 and ₦600,000 at the end of year 2. Total profit = ₦1,200,000 − ₦1,000,000 = ₦200,000."}]},{"text":[{"text":"Project B pays ₦200,000 in year 1 and ₦1,000,000 in year 2. Total profit = ₦200,000 as well."}]},{"text":[{"text":"Profit maximisation sees no difference. Now find the NPV."}]},{"text":[{"text":"A: 600,000 / 1.1 = ₦545,454.55; 600,000 / 1.1^2 = ₦495,867.77. PV = ₦1,041,322.31. NPV = 1,041,322.31 − 1,000,000 = "},{"text":"₦41,322.31","bold":true},{"text":"."}]},{"text":[{"text":"B: 200,000 / 1.1 = ₦181,818.18; 1,000,000 / 1.1^2 = ₦826,446.28. PV = ₦1,008,264.46. NPV = "},{"text":"₦8,264.46","bold":true},{"text":"."}]},{"text":[{"text":"A adds more wealth because its money arrives sooner. (Figures rounded to the nearest kobo.)"}]}]}]},{"text":[{"text":"Worked example (what wealth is).","bold":true},{"text":" You hold 2,000 shares in an NGX-listed bank. The price rises from ₦25 to ₦30 over the year and the bank pays a dividend of ₦2 per share. Gain in wealth = 2,000 × (30 − 25 + 2) = "},{"text":"₦14,000","bold":true},{"text":". Wealth comes from "},{"text":"share price and dividends","bold":true},{"text":", not from the firm's reported profit as such."}]},{"text":[{"text":"Traps:","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Shareholder wealth is the "},{"text":"market price","bold":true},{"text":" per share, "},{"text":"not","bold":true},{"text":" book value (assets less liabilities at historical cost), the number of employees or salaries paid."}]},{"text":[{"text":"\"Which is "},{"text":"not","bold":true},{"text":" a reason SWM is superior?\" Look for the option that "},{"text":"reverses","bold":true},{"text":" a true point: \"wealth maximisation does "},{"text":"not","bold":true},{"text":" consider the timing of returns while profit maximisation does\" is false, so it is the answer. Likewise \"recognition of the prospects of a firm "},{"text":"in the short run","bold":true},{"text":"\" is not a reason; SWM is about the "},{"text":"long run","bol$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin101', 7, $study_guide$d":true},{"text":"."}]},{"text":[{"text":"Genuine reasons include: explicit consideration of risk, consideration of the time value of money, recognition of shareholders' perception of returns from investment (through the share price), and long-term prospects."}]},{"text":[{"text":"\"Most appropriate objective of a business organisation\" → "},{"text":"maximise shareholder wealth","bold":true},{"text":". Long-term earnings growth ignores risk; efficient use of resources and minimising input costs are means, not the goal."}]}]}]}]}]},{"number":"2.3","title":"Other objectives of a firm","mustKnow":[{"type":"paragraph","text":[{"text":"The "},{"text":"6 objectives","bold":true},{"text":" of a business firm:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Profit maximisation","bold":true},{"text":" (Lesson 2.1)."}]},{"text":[{"text":"Shareholders' wealth maximisation","bold":true},{"text":" (Lesson 2.2)."}]},{"text":[{"text":"Satisfaction objective:","bold":true},{"text":" giving "},{"text":"all participants (stakeholders) a satisfactory return","bold":true},{"text":" for their inputs or efforts: customers, shareholders, government, employees, competitors and creditors. Satisfying these interest groups makes a modern firm grow or remain afloat. Satisfied customers stay loyal, recommend the firm and bring repeat business."}]},{"text":[{"text":"Social responsibility objective:","bold":true},{"text":" firms not only make money but also "},{"text":"improve the environment","bold":true},{"text":" they operate in through "},{"text":"community development","bold":true},{"text":": rural electrification, pipe-borne water, good roads, hospitals, scholarships and jobs for indigenes. This objective "},{"text":"enhances a good business environment","bold":true},{"text":"."}]},{"text":[{"text":"Survival objective:","bold":true},{"text":" "},{"text":"staying in business continuously","bold":true},{"text":" rather than making profit this year and packing up next year. In an economic downturn it is the "},{"text":"most important","bold":true},{"text":" objective; keen competition and high inflation in Nigeria make it crucial."}]},{"text":[{"text":"Increase in market share objective:","bold":true},{"text":" "},{"text":"capturing more of the market demand","bold":true},{"text":" for the firm's products or services in the industry, so as to maintain a "},{"text":"leadership position","bold":true},{"text":" (be a market leader)."}]}]},{"type":"paragraph","text":[{"text":"Other objectives of business firms (6):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"To seek "},{"text":"growth","bold":true},{"text":" of the firm."}]},{"text":[{"text":"To improve "},{"text":"productivity","bold":true},{"text":"."}]},{"text":[{"text":"To seek "},{"text":"diversification","bold":true},{"text":"."}]},{"text":[{"text":"To be a "},{"text":"technical leader","bold":true},{"text":" in their field."}]},{"text":[{"text":"To maintain a "},{"text":"contented workforce","bold":true},{"text":"."}]},{"text":[{"text":"To give the "},{"text":"highest quality services","bold":true},{"text":" to customers."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Satisficing:","bold":true},{"text":" aiming for results that are \"good enough\" for every group rather than the maximum for one group. Managers balance owners, workers, lenders, suppliers and government. This is the same idea as the satisfaction objective."}]},{"text":[{"text":"Sales (revenue) maximisation:","bold":true},{"text":" managers may push sales volume, since their status and pay often rise with the size of the firm, even when profit does not rise as fast."}]},{"text":[{"text":"Growth:","bold":true},{"text":" getting bigger, for example by "},{"text":"entering untapped markets","bold":true},{"text":", launching products or adding capacity. "},{"text":"Expanding market presence","bold":true},{"text":" is a "},{"text":"long-term","bold":true},{"text":" objective; covering daily operating costs and hiring short-term workers are short-run matters."}]},{"text":[{"text":"Liquidity:","bold":true},{"text":" "},{"text":"ensuring cash for short-term needs","bold":true},{"text":" (wages, supplier bills) as they fall due."}]},{"text":[{"text":"Efficiency:","bold":true},{"text":" "},{"text":"lowering costs and boosting output","bold":true},{"text":"."}]},{"text":[{"text":"Innovation:","bold":true},{"text":" leads to "},{"text":"greater market penetration","bold":true},{"text":" and also "},{"text":"higher short-term expenses","bold":true},{"text":" (research and development), so \"both\" is the answer when both appear."}]},{"text":[{"text":"Ethical objective:","bold":true},{"text":" "},{"text":"adhering to equitable (fair) practices","bold":true},{"text":", obeying the law and being transparent."}]},{"text":[{"text":"Secondary objectives:","bold":true},{"text":" beside profit or wealth, a firm may pursue "},{"text":"corporate social responsibility","bold":true},{"text":" initiatives. A "},{"text":"social objective","bold":true},{"text":" is one like "},{"text":"enhancing community welfare","bold":true},{"text":"; boosting margins is a profit objective, not a social one."}]},{"text":[{"text":"Economic vs social objectives:","bold":true},{"text":" economic analysis of a firm looks at commercial performance: "},{"text":"sales growth, market share, profits and return on investment","bold":true},{"text":". "},{"text":"Conservation of natural resources","bold":true},{"text":" is a social or environmental concern, "},{"text":"not","bold":true},{"text":" an economic analysis."}]},{"text":[{"text":"Matching cues: \"good business environment\" → social responsibility; \"staying afloat in a downturn\" → survival; \"satisfactory returns to all for their inputs\" → satisfaction; \"capturing more market demand\" → increase in market share."}]}]}]},{"number":"2.4","title":"Stakeholders, the agency problem and objectives o$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin101', 8, $study_guide$f financial decisions","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Stakeholders (interest groups):","bold":true},{"text":" everyone with an interest in the firm: "},{"text":"shareholders, employees, customers, creditors (lenders, suppliers), government, competitors, management","bold":true},{"text":" and the "},{"text":"community","bold":true},{"text":"."}]},{"text":[{"text":"Agency relationship:","bold":true},{"text":" shareholders ("},{"text":"principals","bold":true},{"text":") appoint managers ("},{"text":"agents","bold":true},{"text":") to run the firm for them. This separation of ownership from control comes with the limited liability company."}]},{"text":[{"text":"Agency problem:","bold":true},{"text":" the conflict that arises when managers pursue "},{"text":"their own interests","bold":true},{"text":" (high pay, perks, job security, a bigger firm) instead of maximising shareholders' wealth."}]},{"text":[{"text":"Agency costs:","bold":true},{"text":" costs borne by shareholders to reduce or live with the agency problem:"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Monitoring costs:","bold":true},{"text":" external audit, board oversight, reports."}]},{"text":[{"text":"Bonding and incentive costs:","bold":true},{"text":" costs of tying managers to owners' interests, such as contractual guarantees, bonuses, share options and performance-linked pay."}]},{"text":[{"text":"Residual loss:","bold":true},{"text":" value still lost because managers' and owners' interests are never perfectly aligned."}]}]}]},{"text":[{"text":"Objectives of financial decisions","bold":true},{"text":" (all aim to maximise the "},{"text":"market price per share","bold":true},{"text":"):"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Investment decision:","bold":true},{"text":" allocate capital to proposals that yield future benefits (positive NPV) meeting investors' expectations."}]},{"text":[{"text":"Financing decision:","bold":true},{"text":" find the best financing mix (capital structure): funds at the "},{"text":"cheapest cost","bold":true},{"text":", most favourable tax, best mix."}]},{"text":[{"text":"Dividend decision:","bold":true},{"text":" the proportion of earnings to "},{"text":"pay out","bold":true},{"text":" or "},{"text":"retain","bold":true},{"text":", bearing in mind shareholders' wealth."}]},{"text":[{"text":"Liquidity (working capital) decision:","bold":true},{"text":" keep enough liquid resources for day-to-day needs."}]}]}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Signs of the agency problem:","bold":true},{"text":" lavish offices and cars, empire building (growth for its own sake), avoiding good but risky projects to protect jobs, short-termism to hit bonus targets."}]},{"text":[{"text":"Ways to reduce it:","bold":true},{"text":" performance-linked pay and share options; independent non-executive directors; shareholders' votes at the "},{"text":"annual general meeting (AGM)","bold":true},{"text":"; the threat of takeover; the market for managers; and corporate governance rules. In Nigeria, listed firms follow the "},{"text":"Nigerian Code of Corporate Governance 2018","bold":true},{"text":" (issued by the Financial Reporting Council of Nigeria) and "},{"text":"SEC","bold":true},{"text":" rules for public companies."}]},{"text":[{"text":"A second agency conflict exists between "},{"text":"shareholders and creditors","bold":true},{"text":": owners may push managers into very risky projects funded by lenders' money. Lenders protect themselves with loan covenants."}]},{"text":[{"text":"Stakeholder interests can clash: higher wages please employees but cut dividends. SWM, done properly over the long run, still requires treating customers, staff and the community fairly, which is why it is said to give all groups a satisfactory return."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Profit maximisation: maximise revenue, minimise cost; the primary, traditional objective from the early 19th century; easy to measure."}]},{"text":[{"text":"It is attacked by all and sundry: ignores time value of money, ignores risk, profit is undefined, ignores quality, unfair to other interest groups."}]},{"text":[{"text":"SWM = maximise NPV = maximise the market price per share; the main goal of financial management."}]},{"text":[{"text":"NPV = PV of benefits − initial investment; PV = C / (1 + r)^n."}]},{"text":[{"text":"SWM is superior on 8 counts: time value, risk, short/long balance, quality, all groups, yardstick, wooing investors, feasible criteria."}]},{"text":[{"text":"Other objectives: satisfaction, social responsibility (good business environment), survival (most important in a downturn), market share (market leader)."}]},{"text":[{"text":"Also: growth, productivity, diversification, technical leadership, contented workforce, highest quality service; liquidity, efficiency, innovation, ethics."}]},{"text":[{"text":"Agency problem: managers (agents) vs shareholders (principals); agency costs = monitoring, bonding, residual loss."}]},{"text":[{"text":"Investment, financing, dividend and liquidity decisions all aim to maximise market price per share."}]}]}],"theory":{"itemId":"1df01bce-1f01-5a69-a6a6-1c45816fa063","question":[{"type":"paragraph","text":[{"text":"A firm can invest ₦700,000 today in a project that returns ₦300,000 at the end of each of the next 3 years. The required return is 10%. (a) What is the accounting profit? (b) What is the NPV? (c) Does the project increase shareholders' wealth?"}]}]},"practice":[{"topic":"Objectives of a Business Firm","named":false}]}},{"kind":"note","itemId":"05c43d68-0057-5441-bafb-52f92863e0ee","sourceKey":"guide-topic:3","position":3,"payload":{"title":"Analysis of Risk in Financial Decisions","body":"Risk vs uncertainty; the types of risk; the probability method (expected value, variance, standard deviati$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin101', 9, $study_guide$on, coefficient of variation) and the non-probability methods; choosing between securities for a risk-averse or risk-taking investor; the risk-return trade-off; diversification and risk management.","noteType":"guide_topic","number":3,"mustKnow":[{"text":"Risk vs uncertainty; the types of risk; the probability method (expected value, variance, standard deviation, coefficient of variation) and the non-probability methods; choosing between securities for a risk-averse or risk-taking investor; the risk-return trade-off; diversification and risk management."}],"lessons":[{"number":"3.1","title":"Risk, uncertainty and the risk-return trade-off","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Risk:","bold":true},{"text":" the situation in which the future outcome is unknown but the likelihood of its occurrence can be estimated or determined. In other words, the "},{"text":"probability","bold":true},{"text":" of future occurrence "},{"text":"can","bold":true},{"text":" be estimated."}]},{"text":[{"text":"Uncertainty:","bold":true},{"text":" the situation in which the future outcome is unknown and the likelihood of its occurrence "},{"text":"cannot","bold":true},{"text":" be estimated or determined. The probability "},{"text":"cannot","bold":true},{"text":" be estimated."}]},{"text":[{"text":"Risk in finance:","bold":true},{"text":" uncertainty in expected returns; the chance that the actual return differs from the expected return."}]},{"text":[{"text":"Risk-return trade-off:","bold":true},{"text":" higher risk offers higher potential reward; investors take on more risk only if they expect a higher return. A financial manager must balance "},{"text":"risk exposure and potential returns","bold":true},{"text":"."}]},{"text":[{"text":"Risk premium:","bold":true},{"text":" the extra return investors demand, above the risk-free rate, for accepting risk."}]}]},{"type":"table","header":[[],[{"text":"Risk"}],[{"text":"Uncertainty"}]],"rows":[[[{"text":"Outcome known?"}],[{"text":"No"}],[{"text":"No"}]],[[{"text":"Probability can be estimated?"}],[{"text":"Yes","bold":true}],[{"text":"No","bold":true}]],[[{"text":"Can be measured with EV, SD, CV?"}],[{"text":"Yes"}],[{"text":"No"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The difference is only about the "},{"text":"probability","bold":true},{"text":". In both cases you do not know the outcome. If an option says \"the outcome is known\", it describes certainty, not risk."}]},{"text":[{"text":"A Federal Government of Nigeria treasury bill issued through the CBN is treated as almost risk-free. A share on the NGX is risky, so investors expect a higher return on it. If treasury bills pay 18% and an investor wants 25% from a share, the risk premium is 25% − 18% = 7%."}]},{"text":[{"text":"Traps: \"greater risk yields lower gains\" reverses the trade-off; \"minimal risk ensures big returns\" is false. Risk and return are "},{"text":"connected","bold":true},{"text":", not disconnected."}]}]}]},{"number":"3.2","title":"Types of risk","mustKnow":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Business risk:","bold":true},{"text":" concerned with the future uncertainty about a company's operating prospects (sales, costs, profits), even with no debt."}]},{"text":[{"text":"Financial risk:","bold":true},{"text":" concerned with the introduction of "},{"text":"debt","bold":true},{"text":" into a company's capital structure."}]},{"text":[{"text":"Economic risk:","bold":true},{"text":" the risk an organisation faces due to shifts in macroeconomic variables or forces."}]},{"text":[{"text":"Interest rate risk:","bold":true},{"text":" the exposure of a bank's current or future earnings and capital to adverse changes in market rates. It mainly affects "},{"text":"fixed-income assets","bold":true},{"text":" (bonds): when rates rise, bond prices fall."}]},{"text":[{"text":"Market risk:","bold":true},{"text":" the potential for losses arising from factors influencing the overall performance of financial markets. Also called "},{"text":"systematic risk","bold":true},{"text":"."}]},{"text":[{"text":"Liquidity risk:","bold":true},{"text":" the risk of loss from the inability to meet payment obligations in full and on time when they become due; also, difficulty turning assets into cash quickly without losing value."}]}]},{"type":"paragraph","text":[{"text":"Other types you must also know:"}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Credit (default) risk:","bold":true},{"text":" a borrower fails to repay a loan or interest."}]},{"text":[{"text":"Inflation (purchasing power) risk:","bold":true},{"text":" inflation reduces the purchasing power of returns."}]},{"text":[{"text":"Exchange-rate risk:","bold":true},{"text":" losses from changes in exchange rates on foreign dealings."}]},{"text":[{"text":"Operational risk:","bold":true},{"text":" loss from internal failures (human error, technology breakdown)."}]},{"text":[{"text":"Reinvestment risk:","bold":true},{"text":" cash flows must be reinvested at a lower rate."}]},{"text":[{"text":"Systemic risk:","bold":true},{"text":" collapse of an entire market or financial system."}]}]},{"type":"table","header":[[],[{"text":"Systematic (market) risk"}],[{"text":"Unsystematic risk"}]],"rows":[[[{"text":"Affects"}],[{"text":"All firms, the whole market"}],[{"text":"One firm or one sector"}]],[[{"text":"Causes"}],[{"text":"Recession, inflation, interest rate changes"}],[{"text":"Poor leadership, strike, defective product"}]],[[{"text":"Removed by diversification?"}],[{"text":"No","bold":true},{"text":" (non-diversifiable)"}],[{"text":"Yes","bold":true},{"text":" (diversifiable)"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Business risk vs financial risk: a debt-free firm still has business risk. Once it borrows, the fixed interest must be paid whatever happens, which adds financial risk."}]},{"text":[{"text":"A mark$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin101', 10, $study_guide$et-wide economic downturn, a CBN rise in the monetary policy rate or high inflation hits nearly every firm: systematic. A strike at one company is unsystematic."}]},{"text":[{"text":"Naira depreciation hurts a Lagos importer paying suppliers in dollars: exchange-rate risk."}]},{"text":[{"text":"Do not confuse "},{"text":"systematic","bold":true},{"text":" (market-wide) with "},{"text":"systemic","bold":true},{"text":" (the whole system collapsing). Market risk is never \"diversifiable\" or \"firm-specific\"."}]}]}]},{"number":"3.3","title":"Measuring risk: the probability method","mustKnow":[{"type":"paragraph","text":[{"text":"2 ways of treating risk:","bold":true},{"text":" (1) probability method, (2) non-probability method."}]},{"type":"paragraph","text":[{"text":"Probability method (4 measures):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Expected return (mean, expected value)"}]},{"text":[{"text":"Variance"}]},{"text":[{"text":"Standard deviation"}]},{"text":[{"text":"Coefficient of variation"}]}]},{"type":"paragraph","text":[{"text":"Formulas","bold":true},{"text":" (P = probability, R = return or cash flow):"}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Expected return: ER = Σ (P × R)"}]},{"text":[{"text":"Variance = Σ P × (R − ER)^2"}]},{"text":[{"text":"Standard deviation (SD) = square root of variance"}]},{"text":[{"text":"Coefficient of variation (CV) = SD / ER × 100 (in %)"}]},{"text":[{"text":"Check: the probabilities must add up to 1. The returns with their probabilities form a "},{"text":"probability distribution","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Decision rules:","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"The higher the variance, SD and CV, the higher the risk, and vice versa."}]},{"text":[{"text":"Risk-averse","bold":true},{"text":" investor: selects the security with the "},{"text":"lowest","bold":true},{"text":" risk (variance, SD or CV)."}]},{"text":[{"text":"Risk-taker (risk-seeking)","bold":true},{"text":" investor: selects the security with the "},{"text":"highest","bold":true},{"text":" risk."}]},{"text":[{"text":"Risk-neutral","bold":true},{"text":" investor: ignores risk and looks only at expected return."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Worked example.","bold":true},{"text":" James is considering two securities."}]},{"type":"paragraph","text":[{"text":"Security A: ₦4,000 (0.4), ₦5,000 (0.5), ₦6,000 (0.1)."}]},{"type":"paragraph","text":[{"text":"Security B: ₦6,000 (0.7), ₦4,000 (0.2), ₦3,000 (0.1)."}]},{"type":"paragraph","text":[{"text":"Step 1: P × R, summed, gives ER. Step 2: subtract ER from each return. Step 3: square and multiply by P, summed, gives the variance.","italic":true}]},{"type":"paragraph","text":[{"text":"Security A","bold":true}]},{"type":"table","header":[[{"text":"Return (R)"}],[{"text":"P"}],[{"text":"P × R"}],[{"text":"R − ER"}],[{"text":"(R − ER)^2"}],[{"text":"P × (R − ER)^2"}]],"rows":[[[{"text":"4,000"}],[{"text":"0.4"}],[{"text":"1,600"}],[{"text":"−700"}],[{"text":"490,000"}],[{"text":"196,000"}]],[[{"text":"5,000"}],[{"text":"0.5"}],[{"text":"2,500"}],[{"text":"300"}],[{"text":"90,000"}],[{"text":"45,000"}]],[[{"text":"6,000"}],[{"text":"0.1"}],[{"text":"600"}],[{"text":"1,300"}],[{"text":"1,690,000"}],[{"text":"169,000"}]],[[{"text":"Total"}],[{"text":"1.0"}],[{"text":"ER = 4,700","bold":true}],[],[],[{"text":"Variance = 410,000","bold":true}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"SD = square root of 410,000 = ₦640.31 (₦640 to the nearest naira)"}]},{"text":[{"text":"CV = 640.31 / 4,700 × 100 = 13.62%, about "},{"text":"14%","bold":true}]}]},{"type":"paragraph","text":[{"text":"Security B","bold":true}]},{"type":"table","header":[[{"text":"Return (R)"}],[{"text":"P"}],[{"text":"P × R"}],[{"text":"R − ER"}],[{"text":"(R − ER)^2"}],[{"text":"P × (R − ER)^2"}]],"rows":[[[{"text":"6,000"}],[{"text":"0.7"}],[{"text":"4,200"}],[{"text":"700"}],[{"text":"490,000"}],[{"text":"343,000"}]],[[{"text":"4,000"}],[{"text":"0.2"}],[{"text":"800"}],[{"text":"−1,300"}],[{"text":"1,690,000"}],[{"text":"338,000"}]],[[{"text":"3,000"}],[{"text":"0.1"}],[{"text":"300"}],[{"text":"−2,300"}],[{"text":"5,290,000"}],[{"text":"529,000"}]],[[{"text":"Total"}],[{"text":"1.0"}],[{"text":"ER = 5,300","bold":true}],[],[],[{"text":"Variance = 1,210,000","bold":true}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"SD = square root of 1,210,000 = ₦1,100"}]},{"text":[{"text":"CV = 1,100 / 5,300 × 100 = 20.75%, about "},{"text":"21%","bold":true}]}]},{"type":"paragraph","text":[{"text":"Recommendation:","bold":true},{"text":" James is risk averse, so recommend "},{"text":"Security A","bold":true},{"text":": its variance, SD and CV are all lower than B's (lower risk)."}]},{"type":"paragraph","text":[{"text":"Shortcut check for the variance:","bold":true},{"text":" Variance = Σ (P × R^2) − ER^2. For A: 0.4(16,000,000) + 0.5(25,000,000) + 0.1(36,000,000) = 22,500,000; 22,500,000 − 4,700^2 = 22,500,000 − 22,090,000 = 410,000. Same answer."}]},{"type":"paragraph","text":[{"text":"Traps:","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Variance is in squared units and is huge (e.g. 44,000,000); SD is its square root (e.g. 6,633.25). Options often place both side by side. Read which one is asked."}]},{"text":[{"text":"Options also list the separate terms of a sum (e.g. 15,000, 18,000, 28,000) as distractors. Always add the whole column."}]},{"text":[{"text":"\"Nearest whole percent\": "},{"text":"round","bold":true},{"text":", do not cut off. 13.7% becomes 14%, not 13%. Keep SD to 2 decimal places before dividing."}]},{"text":[{"text":"\"Expected value\", \"expected return\", \"mean\" and \"expected cash flow\" all mean ER."}]}]}]},{"number":"3.4","title":"Comparing securities and the coefficient of variation","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin101', 11, $study_guide${"text":"CV = risk per naira of expected return.","bold":true},{"text":" When expected returns differ, the CV is the fairest comparison."}]},{"text":[{"text":"If SD and CV point to different securities, a risk-averse investor goes by the "},{"text":"lowest CV","bold":true},{"text":"."}]},{"text":[{"text":"Reversing the order of the probabilities on equally spaced returns changes ER and CV but leaves variance and SD "},{"text":"unchanged","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Worked example 1: a risk taker.","bold":true},{"text":" Willy is a risk taker."}]},{"type":"paragraph","text":[{"text":"Security X: ₦5,000 (0.1), ₦6,000 (0.3), ₦7,000 (0.6)."}]},{"type":"paragraph","text":[{"text":"Security Y: ₦8,000 (0.2), ₦7,000 (0.4), ₦6,000 (0.4)."}]},{"type":"table","header":[[{"text":"Security X"}],[{"text":"P"}],[{"text":"P × R"}],[{"text":"R − ER"}],[{"text":"P × (R − ER)^2"}]],"rows":[[[{"text":"5,000"}],[{"text":"0.1"}],[{"text":"500"}],[{"text":"−1,500"}],[{"text":"225,000"}]],[[{"text":"6,000"}],[{"text":"0.3"}],[{"text":"1,800"}],[{"text":"−500"}],[{"text":"75,000"}]],[[{"text":"7,000"}],[{"text":"0.6"}],[{"text":"4,200"}],[{"text":"500"}],[{"text":"150,000"}]],[[{"text":"Total"}],[],[{"text":"6,500","bold":true}],[],[{"text":"450,000","bold":true}]]]},{"type":"table","header":[[{"text":"Security Y"}],[{"text":"P"}],[{"text":"P × R"}],[{"text":"R − ER"}],[{"text":"P × (R − ER)^2"}]],"rows":[[[{"text":"8,000"}],[{"text":"0.2"}],[{"text":"1,600"}],[{"text":"1,200"}],[{"text":"288,000"}]],[[{"text":"7,000"}],[{"text":"0.4"}],[{"text":"2,800"}],[{"text":"200"}],[{"text":"16,000"}]],[[{"text":"6,000"}],[{"text":"0.4"}],[{"text":"2,400"}],[{"text":"−800"}],[{"text":"256,000"}]],[[{"text":"Total"}],[],[{"text":"6,800","bold":true}],[],[{"text":"560,000","bold":true}]]]},{"type":"table","header":[[],[{"text":"ER"}],[{"text":"Variance"}],[{"text":"SD"}],[{"text":"CV"}]],"rows":[[[{"text":"X"}],[{"text":"₦6,500"}],[{"text":"450,000"}],[{"text":"₦670.82"}],[{"text":"10.32% (about 10%)"}]],[[{"text":"Y"}],[{"text":"₦6,800"}],[{"text":"560,000"}],[{"text":"₦748.33"}],[{"text":"11.01% (about 11%)"}]]]},{"type":"paragraph","text":[{"text":"Willy is a risk taker, so recommend "},{"text":"Security Y","bold":true},{"text":": its variance, SD and CV are the highest."}]},{"type":"paragraph","text":[{"text":"Worked example 2: SD and CV disagree.","bold":true},{"text":" Security P has ER ₦10,000 and SD ₦1,500. Security Q has ER ₦40,000 and SD ₦4,000."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"CV of P = 1,500 / 10,000 × 100 = 15%"}]},{"text":[{"text":"CV of Q = 4,000 / 40,000 × 100 = 10%"}]}]},{"type":"paragraph","text":[{"text":"Q has the larger SD but carries less risk per naira, so a risk-averse investor chooses "},{"text":"Q","bold":true},{"text":" (lowest CV). The same thing happens with three or four securities: compute the CV of each and pick the lowest. A four-outcome table is worked exactly like a three-outcome table, with one more row."}]},{"type":"paragraph","text":[{"text":"Worked example 3: reversed probabilities.","bold":true},{"text":" Returns ₦10,000, ₦20,000, ₦30,000."}]},{"type":"table","header":[[{"text":"Probabilities"}],[{"text":"ER"}],[{"text":"Variance"}],[{"text":"SD"}],[{"text":"CV"}]],"rows":[[[{"text":"0.2, 0.3, 0.5"}],[{"text":"₦23,000"}],[{"text":"61,000,000"}],[{"text":"₦7,810.25"}],[{"text":"33.96% (about 34%)"}]],[[{"text":"0.5, 0.3, 0.2"}],[{"text":"₦17,000"}],[{"text":"61,000,000"}],[{"text":"₦7,810.25"}],[{"text":"45.94% (about 46%)"}]]]},{"type":"paragraph","text":[{"text":"The spread is a mirror image, so variance and SD are identical, but ER moves, so CV changes. Do not reuse a CV from one version for the other."}]}]},{"number":"3.5","title":"Non-probability methods, diversification and risk management","mustKnow":[{"type":"paragraph","text":[{"text":"Non-probability methods (5):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Sensitivity analysis"}]},{"text":[{"text":"Payback period"}]},{"text":[{"text":"Risk-adjusted method (risk-adjusted discount rate)"}]},{"text":[{"text":"Certainty equivalent factor"}]},{"text":[{"text":"Simulation"}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Portfolio:","bold":true},{"text":" a combination (collection) of financial investments, such as shares and bonds, held by one investor."}]},{"text":[{"text":"Diversification:","bold":true},{"text":" spreading investments across different assets or industries to reduce risk. It reduces "},{"text":"unsystematic","bold":true},{"text":" risk only."}]},{"text":[{"text":"Risk management:","bold":true},{"text":" identifying, assessing and reducing (or controlling) risks. It never eliminates all uncertainty."}]}]},{"type":"paragraph","text":[{"text":"6 steps in risk analysis:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Identify risks (brainstorming, expert consultation, checklists)"}]},{"text":[{"text":"Measure risks (sensitivity analysis, scenario analysis, Monte Carlo simulation)"}]},{"text":[{"text":"Assess risk tolerance"}]},{"text":[{"text":"Evaluate the risk-return trade-off (metrics such as risk-adjusted return, e.g. the Sharpe ratio, plus NPV and IRR)"}]},{"text":[{"text":"Develop risk mitigation strategies"}]},{"text":[{"text":"Monitor and review risks"}]}]},{"type":"paragraph","text":[{"text":"Mitigation strategies:","bold":true},{"text":" "},{"text":"hedging","bold":true},{"text":" (with derivatives such as options, futures, forwards), "},{"text":"diversification","bold":true},{"text":", "},{"text":"insurance","bold":true},{"text":" (transferring risk to an insurer). Risk can be reduced, transferred or managed."}]},{"type":"paragraph","text":[{"text":"Other tools:","bold":true},{"text":" ratio analysis (debt-to-equity, interest cover), Value at Risk (VaR), scenario and sensitivity analysis, risk mapping (heat maps), Monte Carlo simulation,$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin101', 12, $study_guide$ stress testing."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Sensitivity analysis","bold":true},{"text":" tests how changes in one key variable (say, selling price) affect the outcome; "},{"text":"scenario analysis","bold":true},{"text":" changes several at once (best, likely, worst case); "},{"text":"simulation","bold":true},{"text":" (Monte Carlo) uses computer models and probability distributions to generate many possible outcomes."}]},{"text":[{"text":"Payback period","bold":true},{"text":" treats risk by preferring projects that return their cost faster. "},{"text":"Certainty equivalent","bold":true},{"text":" converts risky cash flows into the certain amounts the investor would accept instead. "},{"text":"Risk-adjusted discount rate","bold":true},{"text":" adds a risk premium to the discount rate for riskier projects."}]},{"text":[{"text":"VaR","bold":true},{"text":" measures the possible loss in value of an investment over a period under normal conditions. "},{"text":"Stress testing","bold":true},{"text":" simulates extreme conditions. A "},{"text":"heat map","bold":true},{"text":" plots risks by probability and impact."}]},{"text":[{"text":"Diversification in practice: an investor holding only one bank's shares on the NGX loses heavily if that bank has a fraud scandal. Holding bank, telecom, consumer goods and oil shares plus treasury bills means one loss can be offset by gains elsewhere. A recession still hurts all of them: systematic risk remains."}]},{"text":[{"text":"Traps: concentrating funds in one asset, raising debt (leverage) and narrowing the investment scope "},{"text":"increase","bold":true},{"text":" risk. Avoiding all investments is not risk management; it gives up return."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Risk: outcome unknown, probability "},{"text":"can","bold":true},{"text":" be estimated. Uncertainty: probability "},{"text":"cannot","bold":true},{"text":" be estimated."}]},{"text":[{"text":"Business risk = operating prospects; financial risk = debt in the capital structure; market risk = systematic risk."}]},{"text":[{"text":"Probability method: ER = Σ(P × R); variance = Σ P(R − ER)^2; SD = square root of variance; CV = SD / ER × 100."}]},{"text":[{"text":"Higher variance, SD, CV = higher risk. Risk averse picks the lowest; risk taker picks the highest; use CV when expected returns differ."}]},{"text":[{"text":"Round CV to the nearest percent; never mix up variance (huge) and SD (its square root)."}]},{"text":[{"text":"Non-probability methods: sensitivity analysis, payback period, risk-adjusted method, certainty equivalent, simulation."}]},{"text":[{"text":"Higher risk, higher potential return; the risk premium is the extra return for bearing risk."}]},{"text":[{"text":"Diversification removes unsystematic risk only; hedging, diversification and insurance manage risk."}]}]}],"theory":{"itemId":"8d2a2b51-0d6b-55e6-8a93-ea787c2b13d8","question":[{"type":"paragraph","text":[{"text":"A project's cash flows and probabilities are ₦10,000 (0.2), ₦15,000 (0.3), ₦20,000 (0.4) and ₦30,000 (0.1). Calculate the expected value, variance, standard deviation and coefficient of variation."}]}]},"practice":[{"topic":"Analysis of Risk in Financial Decisions","named":false}]}},{"kind":"note","itemId":"1ce084b9-4f97-5cc2-8271-1e50075f3483","sourceKey":"guide-topic:4","position":4,"payload":{"title":"Foundation of Financial Mathematics","body":"Time value of money; simple and compound interest; future and present value of a lump sum (including intra-year and continuous compounding); effective vs nominal rates; solving for time and rate; annuities (ordinary, due, deferred), perpetuities, sinking funds and loan amortisation; arithmetic and geometric progressions; investment, consumption and exchange.","noteType":"guide_topic","number":4,"mustKnow":[{"text":"Time value of money; simple and compound interest; future and present value of a lump sum (including intra-year and continuous compounding); effective vs nominal rates; solving for time and rate; annuities (ordinary, due, deferred), perpetuities, sinking funds and loan amortisation; arithmetic and geometric progressions; investment, consumption and exchange."}],"lessons":[{"number":"4.1","title":"Time value of money, simple and compound interest","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Time value of money (TVM):","bold":true},{"text":" money has different values at different times. A naira today is worth "},{"text":"more","bold":true},{"text":" than a naira tomorrow (present funds outvalue future funds). TVM is a fundamental concept in "},{"text":"finance and investment decisions","bold":true},{"text":", because the "},{"text":"timing","bold":true},{"text":" of cash flows affects which choice is best. Its key components are "},{"text":"future value","bold":true},{"text":" and "},{"text":"present value","bold":true},{"text":"."}]},{"text":[{"text":"Interest:","bold":true},{"text":" the payment made for the use of money."}]},{"text":[{"text":"Why a naira today is worth more:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"People prefer to consume now rather than later."}]},{"text":[{"text":"Money held today can be invested to earn interest."}]},{"text":[{"text":"Inflation reduces what money will buy later."}]},{"text":[{"text":"A future receipt is uncertain (risk)."}]}]}]},{"text":[{"text":"Simple interest:","bold":true},{"text":" interest earned on the "},{"text":"original amount invested (principal)","bold":true},{"text":" only. The principal and the yearly interest stay the same from period to period."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"SI = P × R × T (P = principal, R = rate per year as a decimal, T = time in years)"}]},{"text":[{"text":"A = P + PRT = P(1 + RT) (A = total amount at the end)"}]},{"text":[{"text":"P = A ÷ (1 + RT)"}]}]}]},{"text":[{$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin101', 13, $study_guide$"text":"Compound interest:","bold":true},{"text":" interest earned on the "},{"text":"principal plus previously earned interest","bold":true},{"text":". Interest can be compounded daily, monthly, quarterly, semi-annually or annually."}]},{"text":[{"text":"Compounding:","bold":true},{"text":" the arithmetic process of finding the "},{"text":"final value","bold":true},{"text":" of a payment or series of payments when interest is known."}]},{"text":[{"text":"Banker's (ordinary) interest:","bold":true},{"text":" simple interest worked on a 360-day year; exact interest uses 365 days."}]}]},{"type":"table","header":[[],[{"text":"Simple interest"}],[{"text":"Compound interest"}]],"rows":[[[{"text":"Interest earned on"}],[{"text":"Principal only"}],[{"text":"Principal + past interest"}]],[[{"text":"Yearly interest"}],[{"text":"Constant"}],[{"text":"Rises each year"}]],[[{"text":"Amounts over time"}],[{"text":"Arithmetic progression"}],[{"text":"Geometric progression"}]],[[{"text":"Result"}],[{"text":"Lower"}],[{"text":"Higher (same rate and time)"}]]]}],"explainMore":[{"type":"paragraph","text":[{"text":"Example (simple interest):","italic":true},{"text":" Betty invests ₦100,000 for 3 years at 10% simple interest. SI = 100,000 × 0.1 × 3 = "},{"text":"₦30,000","bold":true},{"text":". For 4 years it is ₦40,000 and for 5 years ₦50,000: the interest rises by the same ₦10,000 each year."}]},{"type":"paragraph","text":[{"text":"Example (amount):","italic":true},{"text":" ₦10,000,000 saved for 3 years at 10% simple interest: A = 10,000,000 + 10,000,000 × 0.1 × 3 = "},{"text":"₦13,000,000","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Example (finding the principal):","italic":true},{"text":" How much must be invested now at 12.5% simple interest to have ₦150,000 in 4 years? P = 150,000 ÷ (1 + 0.125 × 4) = 150,000 ÷ 1.5 = "},{"text":"₦100,000","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Example (compound interest, same ₦100,000 at 10% for 3 years):","italic":true}]},{"type":"table","header":[[{"text":"Year"}],[{"text":"Opening (₦)"}],[{"text":"Interest at 10% (₦)"}],[{"text":"Closing (₦)"}]],"rows":[[[{"text":"1"}],[{"text":"100,000"}],[{"text":"10,000"}],[{"text":"110,000"}]],[[{"text":"2"}],[{"text":"110,000"}],[{"text":"11,000"}],[{"text":"121,000"}]],[[{"text":"3"}],[{"text":"121,000"}],[{"text":"12,100"}],[{"text":"133,100"}]]]},{"type":"paragraph","text":[{"text":"Total interest = "},{"text":"₦33,100","bold":true},{"text":", compared with ₦30,000 under simple interest."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap:","bold":true},{"text":" \"Interest accrues solely on the initial amount\" describes simple, not compound, interest. The simple interest formula is I = P × R × T, not P × R ÷ T."}]},{"text":[{"text":"Trap:","bold":true},{"text":" when an option gives the interest only and another gives principal plus interest, read whether the question asks \"how much interest\" or \"how much will he have\"."}]}]}]},{"number":"4.2","title":"Future value, present value and effective rates of a lump sum","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Lump sum:","bold":true},{"text":" a single amount invested for a specified period at a specified rate."}]},{"text":[{"text":"Future (terminal) value:","bold":true},{"text":" what a sum today grows to. It takes into account the "},{"text":"impact of time on value","bold":true},{"text":"."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"FV = PV × (1 + r)^n"}]},{"text":[{"text":"Compounding m times a year: FV = PV × (1 + r/m)^(n × m). Semi-annual m = 2; every four months m = 3; quarterly m = 4; twice a quarter m = 8; monthly m = 12; twice a month m = 24; weekly m = 52; daily m = 365."}]},{"text":[{"text":"Continuous compounding: FV = PV × e^(r × n), e = 2.71828"}]}]}]},{"text":[{"text":"Present value:","bold":true},{"text":" today's worth of a future cash flow. "},{"text":"Discounting","bold":true},{"text":" is the process of finding it; the "},{"text":"discount rate","bold":true},{"text":" is used to find current value."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"PV = FV ÷ (1 + r)^n = FV × (1 + r)^-n"}]},{"text":[{"text":"With m periods: PV = FV ÷ (1 + r/m)^(n × m); continuous: PV = FV × e^(-r × n)"}]}]}]},{"text":[{"text":"A "},{"text":"higher","bold":true},{"text":" interest rate gives a "},{"text":"lower","bold":true},{"text":" present value; a longer time also lowers PV."}]},{"text":[{"text":"Nominal rate:","bold":true},{"text":" the quoted annual rate. "},{"text":"Effective annual rate (EAR):","bold":true},{"text":" the true yearly rate once the "},{"text":"frequency of compounding","bold":true},{"text":" is allowed for."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"EAR = (1 + r/m)^m - 1; continuous: EAR = e^r - 1"}]}]}]},{"text":[{"text":"Solving for time:","bold":true},{"text":" n = log(FV/PV) ÷ log(1 + r) (log base 10 or ln, both work)"}]},{"text":[{"text":"Solving for the rate:","bold":true},{"text":" r = (FV/PV)^(1/n) - 1; with m periods, r = m × [(FV/PV)^(1/(n × m)) - 1]"}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Example (FV):","italic":true},{"text":" ₦10,000,000 at 10% compounded annually for 3 years: FV = 10,000,000 × 1.1^3 = 10,000,000 × 1.331 = "},{"text":"₦13,310,000","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Example (fractional years):","italic":true},{"text":" ₦800,000 for 4½ years at 12%: FV = 800,000 × 1.12^4.5 = "},{"text":"₦1,332,205","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Example (quarterly):","italic":true},{"text":" ₦20,000,000 for 5 years at 24% compounded quarterly: rate per quarter = 0.24 ÷ 4 = 0.06, periods = 5 × 4 = 20. FV = 20,000,000 × 1.06^20 = 20,000,000 × 3.2071 = "},{"text":"₦64,142,709","bold":true},{"text":" (to the nearest naira)."}]},{"type":"paragraph","text":[{"text":"Example (twice a quarter):","ital$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin101', 14, $study_guide$ic":true},{"text":" ₦100,000 at 24% payable eight times a year for 3 years: 0.24 ÷ 8 = 0.03, 3 × 8 = 24 periods. FV = 100,000 × 1.03^24 = "},{"text":"₦203,279.41","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Example (continuous):","italic":true},{"text":" ₦15,000,000 at 16% for 2 years: FV = 15,000,000 × e^(0.32) = 15,000,000 × 1.3771 = "},{"text":"₦20,656,916","bold":true},{"text":" (₦20,656,500 if you round e^0.32 to 1.3771 first). Effective rate = e^0.16 - 1 = 0.1735 = "},{"text":"17.35%","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Example (PV):","italic":true},{"text":" ₦14,400,000 due in 2 years at 20%: PV = 14,400,000 ÷ 1.2^2 = 14,400,000 ÷ 1.44 = "},{"text":"₦10,000,000","bold":true},{"text":". ₦7,500,000 due in 5 years at 20% compounded continuously: PV = 7,500,000 × e^(-1) = "},{"text":"₦2,759,096","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Example (PV, semi-annual):","italic":true},{"text":" ₦10m due in 5 years at 10% payable semi-annually: 5% for 10 periods. PV = 10m ÷ 1.05^10 = 10m ÷ 1.6289 = "},{"text":"₦6.14m","bold":true},{"text":". Using 10% annually (₦6.21m) is the trap."}]},{"type":"paragraph","text":[{"text":"Example (EAR):","italic":true},{"text":" 24% compounded quarterly: EAR = 1.06^4 - 1 = "},{"text":"26.25%","bold":true},{"text":". The more often interest is compounded, the higher the EAR: annual < quarterly < monthly < continuous."}]},{"type":"paragraph","text":[{"text":"Example (time):","italic":true},{"text":" How long for ₦3.5m to reach ₦45m at 25%? 1.25^n = 45 ÷ 3.5 = 12.8571. n = log 12.8571 ÷ log 1.25 = 1.1091 ÷ 0.0969 = "},{"text":"11.45 years, 11 years to the nearest year","bold":true},{"text":". Round as the question says: \"to the nearest year\" means normal rounding."}]},{"type":"paragraph","text":[{"text":"Example (doubling, tripling, quadrupling):","italic":true},{"text":" the PV cancels. To quadruple at 12%: 1.12^n = 4, n = log 4 ÷ log 1.12 = 0.6021 ÷ 0.0492 = "},{"text":"12.23 years","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Example (time with quarterly compounding):","italic":true},{"text":" ₦2m to ₦3m at 12% compounded quarterly: 1.03^k = 1.5, k = log 1.5 ÷ log 1.03 = 13.72 quarters, so n = 13.72 ÷ 4 = "},{"text":"3.43 years","bold":true},{"text":". Trap: 13.72 is quarters, not years."}]},{"type":"paragraph","text":[{"text":"Example (rate):","italic":true},{"text":" ₦100,000 grows to ₦133,100 in 3 years: (1 + r)^3 = 1.331, 1 + r = 1.331^(1/3) = 1.1, "},{"text":"r = 10%","bold":true},{"text":". With quarterly compounding, ₦10,000 to ₦20,000 in 5 years: (1 + r/4)^20 = 2, r/4 = 2^(0.05) - 1 = 0.03526, "},{"text":"r = 14.10%","bold":true},{"text":" (rounded). Trap: 3.53% is only the quarterly rate."}]}]},{"number":"4.3","title":"Annuities and perpetuities","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Annuity:","bold":true},{"text":" a series of "},{"text":"equal","bold":true},{"text":", regular, periodic payments or receipts for a specified number of periods. It need not be annual: weekly, monthly or any regular interval counts."}]},{"text":[{"text":"Types of annuity (3):","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Ordinary annuity:","bold":true},{"text":" payments at the "},{"text":"end","bold":true},{"text":" of each period."}]},{"text":[{"text":"Annuity due:","bold":true},{"text":" payments at the "},{"text":"beginning","bold":true},{"text":" of each period."}]},{"text":[{"text":"Perpetual annuity (perpetuity):","bold":true},{"text":" equal payments expected "},{"text":"indefinitely","bold":true},{"text":"."}]}]}]},{"text":[{"text":"The "},{"text":"two major types","bold":true},{"text":" are ordinary annuity and annuity due."}]},{"text":[{"text":"FV of ordinary annuity","bold":true},{"text":" (sum of all payments plus compound interest on each): FV = A × [(1 + r)^n - 1] ÷ r"}]},{"text":[{"text":"PV of ordinary annuity","bold":true},{"text":" (amount to invest today to fund the series): PV = A × [1 - (1 + r)^-n] ÷ r"}]},{"text":[{"text":"FV of annuity due:","bold":true},{"text":" FV = A × [(1 + r)^(n+1) - (1 + r)] ÷ r = ordinary FV × (1 + r)"}]},{"text":[{"text":"PV of annuity due:","bold":true},{"text":" PV = A × [(1 + r) - (1 + r)^-(n-1)] ÷ r = ordinary PV × (1 + r)"}]},{"text":[{"text":"PV of perpetuity:","bold":true},{"text":" PV = A ÷ r"}]},{"text":[{"text":"Deferred annuity","bold":true},{"text":" (first payment later than one period away): PV = A × [1 - (1 + r)^-n] ÷ r × (1 + r)^-k, where k = periods of delay before the ordinary annuity starts."}]},{"text":[{"text":"Net present value:","bold":true},{"text":" NPV = PV of inflows - initial cost. Accept if NPV is positive."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Example (FV ordinary):","italic":true},{"text":" ₦20,000,000 deposited at the end of each of 3 years at 20%. Year by year: end of year 1 ₦20m; year 2: 20m + 4m interest + 20m = ₦44m; year 3: 44m + 8.8m + 20m = ₦72.8m. By formula: 20,000,000 × (1.2^3 - 1) ÷ 0.2 = 20,000,000 × 3.64 = "},{"text":"₦72,800,000","bold":true},{"text":". Only two years of interest are earned, because the last payment earns none."}]},{"type":"paragraph","text":[{"text":"Example (FV due):","italic":true},{"text":" the same deposits at the beginning of each year: 20,000,000 × (1.2^4 - 1.2) ÷ 0.2 = "},{"text":"₦87,360,000","bold":true},{"text":", which is 72,800,000 × 1.2."}]},{"type":"paragraph","text":[{"text":"Example (PV ordinary):","italic":true},{"text":" Joshua must pay ₦120,000 at the end of each of 3 years; money earns 12%. PV = 120,000 × [1 - 1.12^-3] ÷ 0.12 = 120,000 × 2.4018 = "},{"text":"₦288,219.75","bold":true},{"text":". Proof: 288,219.75 earns ₦34,586.37 in year 1, leaving 202,806.12 after paying 120,000; then 24,336.73 interest leaves 107,142.85; then 12,857.14 interest leaves 0."}]},{"type":"paragraph","text":[{"text":"Example (PV due):","italic":true},{"text":" the same $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin101', 15, $study_guide$₦120,000 at the beginning of each year: PV = 120,000 × [1.12 - 1.12^-2] ÷ 0.12 = "},{"text":"₦322,806.12","bold":true},{"text":" (= 288,219.75 × 1.12)."}]},{"type":"paragraph","text":[{"text":"Example (perpetuity):","italic":true},{"text":" Chukwu expects ₦250,000 a year forever at 20%: PV = 250,000 ÷ 0.2 = "},{"text":"₦1,250,000","bold":true},{"text":". A bond paying ₦1,200,000 a year in perpetuity at 10% is worth ₦12,000,000."}]},{"type":"paragraph","text":[{"text":"Example (deferred):","italic":true},{"text":" ₦200,000 a year for 5 years, first payment at the end of year 4, at 10%. Value at end of year 3 = 200,000 × 3.7908 = ₦758,157.35. Discount 3 years: 758,157.35 ÷ 1.331 = "},{"text":"₦569,614.84","bold":true},{"text":". Trap: stopping at ₦758,157.35."}]},{"type":"paragraph","text":[{"text":"Example (solving n, ordinary):","italic":true},{"text":" ₦50,000 at the end of each year at 10% to reach ₦500,000: (1.1^n - 1) ÷ 0.1 = 10, so 1.1^n = 2, n = log 2 ÷ log 1.1 = "},{"text":"7.27 years","bold":true},{"text":". For an annuity due, divide by (1 + r) first: 1.1^n = 1 + 500,000 × 0.1 ÷ (50,000 × 1.1) = 1.9091, n = "},{"text":"6.78 years","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Example (NPV):","italic":true},{"text":" a project costs ₦100,000 and returns ₦30,000 a year for 4 years at 8%. PV of inflows = 30,000 × 3.3121 = ₦99,363.81; NPV = 99,363.81 - 100,000 = "},{"text":"-₦636.19","bold":true},{"text":", so reject. Trap: an option showing only the PV of inflows."}]},{"type":"paragraph","text":[{"text":"Mixed streams:","italic":true},{"text":" value each stream at its own rate and add. A monthly salary uses the monthly rate and number of months (3 years = 36 months); a yearly bonus uses the yearly rate and 3 years."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap:","bold":true},{"text":" an annuity due is always worth more than the ordinary annuity by the factor (1 + r), for both PV and FV."}]}]}]},{"number":"4.4","title":"Sinking funds and loan amortisation","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Sinking fund:","bold":true},{"text":" equal periodic deposits made to accumulate a target sum at a future date (an FV-of-annuity problem). Deposit A = FV × r ÷ [(1 + r)^n - 1]"}]},{"text":[{"text":"Loan amortisation:","bold":true},{"text":" repaying a loan by equal instalments that cover interest and part of the principal (a PV-of-annuity problem). Instalment A = Loan × r ÷ [1 - (1 + r)^-n]"}]},{"text":[{"text":"In each instalment, "},{"text":"interest","bold":true},{"text":" = opening balance × r; "},{"text":"principal repaid","bold":true},{"text":" = instalment - interest; closing balance = opening balance - principal repaid."}]},{"text":[{"text":"Outstanding balance","bold":true},{"text":" after k instalments = PV of the instalments still to be paid."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Example (sinking fund):","italic":true},{"text":" a school wants ₦1,000,000 in 4 years, saving at the end of each year at 10%. A = 1,000,000 × 0.1 ÷ (1.1^4 - 1) = 100,000 ÷ 0.4641 = "},{"text":"₦215,470.80","bold":true},{"text":". Fund after 2 years = 215,470.80 × 1.1 + 215,470.80 = 215,470.80 × 2.1 = "},{"text":"₦452,488.69","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Example (amortisation):","italic":true},{"text":" ₦500,000 borrowed at 12% for 3 years. A = 500,000 × 0.12 ÷ (1 - 1.12^-3) = "},{"text":"₦208,174.49","bold":true},{"text":"."}]},{"type":"table","header":[[{"text":"Year"}],[{"text":"Opening (₦)"}],[{"text":"Interest 12% (₦)"}],[{"text":"Principal repaid (₦)"}],[{"text":"Closing (₦)"}]],"rows":[[[{"text":"1"}],[{"text":"500,000.00"}],[{"text":"60,000.00"}],[{"text":"148,174.49"}],[{"text":"351,825.51"}]],[[{"text":"2"}],[{"text":"351,825.51"}],[{"text":"42,219.06"}],[{"text":"165,955.43"}],[{"text":"185,870.08"}]],[[{"text":"3"}],[{"text":"185,870.08"}],[{"text":"22,304.41"}],[{"text":"185,870.08"}],[{"text":"0.00"}]]]},{"type":"paragraph","text":[{"text":"Shortcut: balance after year 2 = one instalment left = 208,174.49 ÷ 1.12 = ₦185,870.08. Interest falls and principal repaid rises each year."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap:","bold":true},{"text":" the instalment is not the balance; and a sinking-fund deposit is not the fund balance."}]}]}]},{"number":"4.5","title":"Arithmetic and geometric progressions","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Arithmetic progression (AP):","bold":true},{"text":" each term differs from the one before by a constant "},{"text":"common difference d","bold":true},{"text":". First term a."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"nth term: Tn = a + (n - 1)d"}]},{"text":[{"text":"Sum of n terms: Sn = n/2 × [2a + (n - 1)d] = n/2 × (a + l), l = last term"}]},{"text":[{"text":"Number of terms: n = (l - a) ÷ d + 1"}]}]}]},{"text":[{"text":"Geometric progression (GP):","bold":true},{"text":" each term is the one before multiplied by a constant "},{"text":"common ratio r","bold":true},{"text":"."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"nth term: Tn = a × r^(n-1)"}]},{"text":[{"text":"Sum of n terms: Sn = a × (r^n - 1) ÷ (r - 1) when r > 1, or a × (1 - r^n) ÷ (1 - r) when r < 1"}]},{"text":[{"text":"Sum to infinity (only when -1 < r < 1): S∞ = a ÷ (1 - r)"}]}]}]},{"text":[{"text":"Simple-interest amounts form an AP (d = PR); compound amounts form a GP (ratio 1 + r); annuity formulas are GP sums."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Example (AP):","italic":true},{"text":" 5, 8, 11, ...: a = 5, d = 3. T20 = 5 + 19 × 3 = "},{"text":"62","bold":true},{"text":"; S20 = 20/2 × (5 + 62) = "},{"text":"670","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Example (AP in naira):","italic":true},{"text":" a salary of ₦600,000 rising by ₦50,000 a year. Year 10 salary = 600,000 + 9 × 50,000 = "},{"text":"₦1,050,00$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin101', 16, $study_guide$0","bold":true},{"text":"; total over 10 years = 10/2 × (600,000 + 1,050,000) = "},{"text":"₦8,250,000","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Example (GP):","italic":true},{"text":" 2, 6, 18, ...: a = 2, r = 3. T6 = 2 × 3^5 = "},{"text":"486","bold":true},{"text":"; S6 = 2 × (3^6 - 1) ÷ (3 - 1) = "},{"text":"728","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Example (sum to infinity):","italic":true},{"text":" ₦100,000 + ₦80,000 + ₦64,000 + ...: r = 0.8, S∞ = 100,000 ÷ (1 - 0.8) = "},{"text":"₦500,000","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Why annuity formulas work:","italic":true},{"text":" the end-year deposits of ₦20m at 20% grow to 20m, 24m and 28.8m: a GP with a = 20m, r = 1.2, n = 3. S3 = 20m × (1.2^3 - 1) ÷ 0.2 = ₦72.8m, the FV of the annuity. A perpetuity is a GP sum to infinity with a = A ÷ (1 + r) and ratio 1 ÷ (1 + r), which simplifies to A ÷ r."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap:","bold":true},{"text":" the nth term uses n - 1, not n. Sum to infinity exists only when -1 < r < 1."}]}]}]},{"number":"4.6","title":"Investment, consumption and exchange","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Each person has income now (Y0) and next period (Y1) and chooses consumption now (C0) and later (C1)."}]},{"text":[{"text":"Lending:","bold":true},{"text":" giving up ₦1 of consumption today gets ₦(1 + r) next period."}]},{"text":[{"text":"Borrowing:","bold":true},{"text":" ₦1 of next period's income can be spent today as ₦1 ÷ (1 + r)."}]},{"text":[{"text":"The interest rate is the "},{"text":"price of exchanging present for future consumption","bold":true},{"text":"."}]},{"text":[{"text":"Present value of wealth:","bold":true},{"text":" W0 = Y0 + Y1 ÷ (1 + r). Maximum future consumption = W0 × (1 + r)."}]},{"text":[{"text":"Budget line:","bold":true},{"text":" C1 = Y1 + (Y0 - C0) × (1 + r); slope = -(1 + r)."}]},{"text":[{"text":"Productive investment:","bold":true},{"text":" invest while the project's return exceeds the market rate (positive NPV). This raises wealth, and every person then borrows or lends to reach the consumption pattern they like."}]},{"text":[{"text":"Separation:","bold":true},{"text":" because people can borrow and lend at r, the investment decision (maximise NPV) is separate from consumption preferences."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Example:","italic":true},{"text":" Ada earns ₦100,000 now and ₦110,000 next year; the rate is 10%. W0 = 100,000 + 110,000 ÷ 1.1 = "},{"text":"₦200,000","bold":true},{"text":"; maximum next-year consumption = 200,000 × 1.1 = ₦220,000."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"To spend ₦150,000 now, she borrows ₦50,000 and repays 50,000 × 1.1 = ₦55,000, leaving C1 = 110,000 - 55,000 = "},{"text":"₦55,000","bold":true},{"text":"."}]},{"text":[{"text":"To spend only ₦60,000 now, she lends ₦40,000 and gets back ₦44,000, so C1 = 110,000 + 44,000 = "},{"text":"₦154,000","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Investment:","italic":true},{"text":" a project costs ₦40,000 now and pays ₦50,000 next year (a 25% return, above 10%). NPV = 50,000 ÷ 1.1 - 40,000 = "},{"text":"₦5,454.55","bold":true},{"text":", so her wealth rises to ₦205,454.55 whatever her tastes. Exchange through banks or treasury bills lets savers (lenders) and spenders (borrowers) both gain."}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A naira today is worth more than a naira tomorrow; compounding moves value forward, discounting moves it back."}]},{"text":[{"text":"SI = PRT and A = P(1 + RT); compound FV = PV(1 + r)^n, or PV(1 + r/m)^(nm), or PV × e^(rn)."}]},{"text":[{"text":"PV = FV(1 + r)^-n; higher rate means lower PV."}]},{"text":[{"text":"EAR = (1 + r/m)^m - 1; continuous EAR = e^r - 1."}]},{"text":[{"text":"n = log(FV/PV) ÷ log(1 + r); r = (FV/PV)^(1/n) - 1."}]},{"text":[{"text":"Ordinary annuity: FV = A[(1 + r)^n - 1]/r, PV = A[1 - (1 + r)^-n]/r; annuity due = ordinary × (1 + r); perpetuity = A/r."}]},{"text":[{"text":"Sinking fund deposit = FV × r/[(1 + r)^n - 1]; loan instalment = Loan × r/[1 - (1 + r)^-n]."}]},{"text":[{"text":"AP: a + (n - 1)d and n/2[2a + (n - 1)d]; GP: ar^(n-1), a(r^n - 1)/(r - 1), a/(1 - r)."}]},{"text":[{"text":"Borrowing and lending at r let people trade present for future consumption; invest when NPV is positive."}]}]}],"theory":{"itemId":"3a6f4bbb-2379-5802-a128-1abedf801b3c","question":[{"type":"paragraph","text":[{"text":"Unilag Ventures deposits ₦150,000 at the end of each year for 4 years at 15% per annum. How much will be in the fund at the end of year 4, and how much if each deposit were made at the beginning of the year?"}]}]},"practice":[{"topic":"Foundation of Financial Mathematics","named":false}]}},{"kind":"note","itemId":"bb3b0b44-2a82-5623-a29f-2c05092a6e5e","sourceKey":"guide-topic:5","position":5,"payload":{"title":"Financial Statement Analysis","body":"The three financial statements and what goes in each; users of financial statements and ratios; methods and limitations of analysis; the four groups of ratios with their other names; every formula for liquidity, activity, profitability, gearing and stock market ratios; ideal benchmarks; how to compute every ratio from one set of statements.","noteType":"guide_topic","number":5,"mustKnow":[{"text":"The three financial statements and what goes in each; users of financial statements and ratios; methods and limitations of analysis; the four groups of ratios with their other names; every formula for liquidity, activity, profitability, gearing and stock market ratios; ideal benchmarks; how to compute every ratio from one set of statements."}],"lessons":[{"number":"5.1","title":"Financial statements, users and methods of analysis","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Financial statement analysis:","bold":true},{"text":" the$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin101', 17, $study_guide$ process of examining a company's financial reports to assess its performance, stability and future prospects, so that stakeholders can make informed decisions."}]},{"text":[{"text":"3 main financial statements:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Statement of financial position (balance sheet):","bold":true},{"text":" assets, liabilities and equity at a "},{"text":"specific point in time","bold":true},{"text":" (one date)."}]},{"text":[{"text":"Income statement (profit and loss account):","bold":true},{"text":" revenue, expenses and net income (profit) "},{"text":"over a period","bold":true},{"text":"; it shows "},{"text":"performance","bold":true},{"text":". Liabilities do "},{"text":"not","bold":true},{"text":" appear in it."}]},{"text":[{"text":"Statement of cash flows:","bold":true},{"text":" actual cash "},{"text":"inflows and outflows","bold":true},{"text":" over a period, in "},{"text":"3 sections:","bold":true},{"text":" operating, investing and financing activities."}]}]}]},{"text":[{"text":"A "},{"text":"trial balance","bold":true},{"text":" is a bookkeeping check (a list of ledger balances), "},{"text":"not","bold":true},{"text":" a financial statement."}]},{"text":[{"text":"Non-current (fixed) assets:","bold":true},{"text":" held for long-term use, not for sale, e.g. "},{"text":"land","bold":true},{"text":", buildings, plant, machinery."}]},{"text":[{"text":"Current assets:","bold":true},{"text":" cash or items that become cash within a year: inventory (stock), accounts receivable (debtors), bank, cash."}]},{"text":[{"text":"Current liabilities:","bold":true},{"text":" obligations to be settled "},{"text":"within 1 year","bold":true},{"text":": trade creditors (accounts payable), bank overdraft, accrued expenses, tax payable."}]},{"text":[{"text":"Shareholders' equity:","bold":true},{"text":" ordinary share capital (common stock), share premium (additional paid-in capital), reserves, retained earnings. Accounts payable is a "},{"text":"liability","bold":true},{"text":", not equity."}]},{"text":[{"text":"Working capital = current assets - current liabilities.","bold":true},{"text":" Its components are current assets and current liabilities; fixed assets, long-term debt and share capital are not part of it. A rise in working capital usually means "},{"text":"higher liquidity","bold":true},{"text":"."}]},{"text":[{"text":"Net profit = total revenue - total expenses.","bold":true},{"text":" Gross profit = sales - cost of goods sold. Operating profit = gross profit - operating expenses."}]},{"text":[{"text":"Liquidity:","bold":true},{"text":" the ease of converting assets to cash. "},{"text":"Leverage:","bold":true},{"text":" using "},{"text":"debt","bold":true},{"text":" to finance investments."}]},{"text":[{"text":"Users of financial ratio analysis (10):","bold":true},{"text":" 1. company management, 2. shareholders, 3. employees, 4. creditors, 5. government, 6. rational investors, 7. competitors, 8. customers, 9. financial analysts, 10. financial institutions."}]},{"text":[{"text":"Internal user:","bold":true},{"text":" management. "},{"text":"External users:","bold":true},{"text":" investors, shareholders, creditors, government and the rest."}]},{"text":[{"text":"5 objectives of analysis:","bold":true},{"text":" assess profitability; evaluate liquidity; measure solvency; understand operational efficiency; support decision-making."}]},{"text":[{"text":"5 methods of analysis:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Horizontal (trend) analysis:","bold":true},{"text":" compares figures across periods. Percentage change = (current year value - base year value) ÷ base year value × 100."}]},{"text":[{"text":"Vertical (common-size) analysis:","bold":true},{"text":" each item as a percentage of a base figure (revenue or total assets)."}]},{"text":[{"text":"Ratio analysis.","bold":true}]},{"text":[{"text":"Cash flow analysis:","bold":true},{"text":" evaluating and comparing cash inflows and outflows from operating, investing and financing activities."}]},{"text":[{"text":"Comparative analysis:","bold":true},{"text":" against industry benchmarks or competitors."}]}]}]},{"text":[{"text":"5 steps:","bold":true},{"text":" understand the business; review the statements; perform trend and ratio analysis; interpret results; make recommendations."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Horizontal example:","italic":true},{"text":" sales rose from ₦800,000 to ₦900,000. Change = (900,000 - 800,000) ÷ 800,000 × 100 = "},{"text":"12.5%","bold":true},{"text":"."}]},{"text":[{"text":"Vertical example:","italic":true},{"text":" cost of sales ₦540,000 on sales ₦900,000 is 540,000 ÷ 900,000 × 100 = "},{"text":"60%","bold":true},{"text":" of sales."}]},{"text":[{"text":"Debtors","bold":true},{"text":" (customers who owe the firm) are "},{"text":"not","bold":true},{"text":" listed as users of ratio analysis; "},{"text":"creditors","bold":true},{"text":" are. Do not confuse them. Customers are users, because they care whether a supplier will survive."}]},{"text":[{"text":"A "},{"text":"financial analyst","bold":true},{"text":" is the user who studies statements in order to "},{"text":"advise clients","bold":true},{"text":". Researchers study them for academic work."}]},{"text":[{"text":"ROI","bold":true},{"text":" stands for "},{"text":"Return on Investment","bold":true},{"text":": gain from an investment relative to its cost, × 100."}]},{"text":[{"text":"Nigerian listed companies publish audited statements and file them with the SEC and the Nigerian Exchange (NGX), which is where investors find the figures for ratios."}]}]}]},{"number":"5.2","title":"Ratio analysis and liquidity ratios","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Financial ratio analysis:","bold":true},{"text":" the relationship between financial data in the financia$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin101', 18, $study_guide$l statements that aids the evaluation of the financial condition and performance of a company. It is used to gauge a firm's operational success and to track performance trends."}]},{"text":[{"text":"Advantages (5):","bold":true},{"text":" 1. very easy to understand; 2. very simple to calculate; 3. allows comparison between two similar companies; 4. allows comparison with the industry average; 5. useful for identifying problem areas of the company."}]},{"text":[{"text":"Disadvantages (4):","bold":true},{"text":" 1. taken by itself, a ratio gives little useful information; 2. ratios are easily misinterpreted; 3. ratios do not identify the causes of a company's problems; 4. problems of definition."}]},{"text":[{"text":"Limitations of financial statement analysis (5):","bold":true},{"text":" historical data; differing accounting policies reduce comparability; non-financial factors (management quality, market conditions) are left out; window dressing; inflation."}]},{"text":[{"text":"4 groups of ratios:","bold":true}]}]},{"type":"table","header":[[{"text":"Group"}],[{"text":"Other names"}],[{"text":"Measures"}]],"rows":[[[{"text":"1. Short-term solvency"}],[{"text":"Liquidity","bold":true},{"text":", working capital ratios"}],[{"text":"Ability to meet current obligations from current assets"}]],[[{"text":"2. Efficiency and profitability"}],[{"text":"Performance ratios"}],[{"text":"Performance in relative terms"}]],[[{"text":"3. Long-term solvency"}],[{"text":"Stability","bold":true},{"text":" ratios, gearing"}],[{"text":"Ability to meet long-term obligations"}]],[[{"text":"4. Stock market"}],[{"text":"Investor interest, actual growth and potential, valuation, market value ratios"}],[{"text":"Help investors make investment decisions"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Liquidity formulas:","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Current ratio = current assets ÷ current liabilities (written as x : 1). "},{"text":"Ideal 2:1.","bold":true}]},{"text":[{"text":"Quick (acid-test) ratio = (current assets - inventory) ÷ current liabilities. "},{"text":"Ideal 1:1.","bold":true},{"text":" Inventory is excluded because it is the least liquid current asset."}]},{"text":[{"text":"Cash ratio = cash and cash equivalents ÷ current liabilities."}]}]}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The "},{"text":"current ratio","bold":true},{"text":" shows how far the claims of short-term creditors are covered by assets that will become cash within a year. Above 1 suggests good liquidity; far too high suggests idle assets. A "},{"text":"low quick ratio","bold":true},{"text":" warns of difficulty paying short-term debts. A very high cash ratio may mean underused cash."}]},{"text":[{"text":"Example 1:","italic":true},{"text":" stock ₦5,000; trade creditors ₦2,000; debtors ₦3,000; bank overdraft ₦1,600; bank ₦1,500; accrued expenses ₦400; cash ₦500."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Current assets = 5,000 + 3,000 + 1,500 + 500 = ₦10,000. Current liabilities = 2,000 + 1,600 + 400 = ₦4,000."}]},{"text":[{"text":"Current ratio = 10,000 ÷ 4,000 = "},{"text":"2.5:1","bold":true},{"text":". Quick ratio = (10,000 - 5,000) ÷ 4,000 = "},{"text":"1.25:1","bold":true},{"text":"."}]}]}]},{"text":[{"text":"Example 2:","italic":true},{"text":" inventories ₦3,100; receivables ₦8,000; payables ₦4,000; cash ₦6,260; taxation ₦2,250."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Current assets = ₦17,360. Current liabilities = 4,000 + 2,250 = ₦6,250 (tax payable is due within the year, so include it)."}]},{"text":[{"text":"Current ratio = 17,360 ÷ 6,250 = "},{"text":"2.78:1","bold":true},{"text":". Quick = 14,260 ÷ 6,250 = "},{"text":"2.28:1","bold":true},{"text":" (both to 2 d.p.)."}]}]}]},{"text":[{"text":"Example 3:","italic":true},{"text":" stock ₦3,000, cash ₦7,000, debtors ₦10,000, trade creditors ₦5,900. Current ratio = 20,000 ÷ 5,900 = "},{"text":"3.4:1","bold":true},{"text":"; acid test = 17,000 ÷ 5,900 = "},{"text":"2.9:1","bold":true},{"text":" (1 d.p.)."}]},{"text":[{"text":"Traps:","bold":true},{"text":" a bank overdraft is a current liability, but money "},{"text":"in","bold":true},{"text":" the bank is a current asset. Options often list the ideal (2:1 or 1:1) beside the firm's actual figure; compute, do not guess the ideal."}]}]}]},{"number":"5.3","title":"Activity (efficiency) ratios","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Activity ratios","bold":true},{"text":" measure how efficiently a firm uses its resources (stock, debtors, assets)."}]},{"text":[{"text":"Inventory (stock) turnover = cost of sales ÷ average stock (in "},{"text":"times","bold":true},{"text":")."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Average stock = (opening stock + closing stock) ÷ 2."}]},{"text":[{"text":"Inventory days = 365 ÷ inventory turnover."}]}]}]},{"text":[{"text":"Average collection period (receivables days) = trade debtors ÷ credit sales × 365 days."}]},{"text":[{"text":"Receivables turnover = credit sales ÷ average receivables (times)."}]},{"text":[{"text":"Average payment period (payables days) = trade creditors ÷ credit purchases × 365 days."}]},{"text":[{"text":"Credit purchases (if not given) = cost of sales + closing stock - opening stock."}]},{"text":[{"text":"Asset turnover = sales ÷ total assets (times)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Stock turnover, the payment period and the collection period are also grouped with the "},{"text":"short-term (working capital) ratios","bold":true},{"text":", because they show how fast stock and debtors turn into cash. Accept either grouping."}]},{"text":[{"text":"Inventory turnover measures the "},{"text":"speed of inventory sales","bold":true},{"text":". A "},{"text":"high receivables turnover","bold":true},{"text":" means "}$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin101', 19, $study_guide$,{"text":"swift collection","bold":true},{"text":" from customers; a low one means slow payment. A long payment period means the firm takes longer to pay suppliers."}]},{"text":[{"text":"Example:","italic":true},{"text":" opening stock ₦13,000, closing stock ₦9,000, cost of sales ₦77,000. Average stock = 0.5 × (13,000 + 9,000) = ₦11,000. Turnover = 77,000 ÷ 11,000 = "},{"text":"7 times","bold":true},{"text":"; inventory days = 365 ÷ 7 = "},{"text":"52.1 days","bold":true},{"text":" (1 d.p.)."}]},{"text":[{"text":"Example:","italic":true},{"text":" credit sales ₦40,000,000; average debtors ₦10,000,000. Receivables turnover = "},{"text":"4 times","bold":true},{"text":"; collection period = 10,000,000 ÷ 40,000,000 × 365 = "},{"text":"91.25 days","bold":true},{"text":"."}]},{"text":[{"text":"Trap:","bold":true},{"text":" stock turnover uses "},{"text":"cost of sales","bold":true},{"text":", not sales; the collection period uses "},{"text":"credit sales","bold":true},{"text":"; the payment period uses "},{"text":"credit purchases","bold":true},{"text":"."}]}]}]},{"number":"5.4","title":"Profitability ratios","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Profitability ratios","bold":true},{"text":" show a firm's ability to generate profit relative to revenue, assets or equity. All are × 100 (%)."}]},{"text":[{"text":"Gross profit margin = gross profit ÷ sales × 100."}]},{"text":[{"text":"Operating profit margin = operating profit (EBIT) ÷ sales × 100."}]},{"text":[{"text":"Net profit margin = net profit ÷ sales × 100 (profit after "},{"text":"all","bold":true},{"text":" costs, including interest and tax). The core formula also allows EBIT as the numerator; follow what the question says."}]},{"text":[{"text":"Return on total assets (ROTA) = EBIT ÷ total assets × 100."}]},{"text":[{"text":"Return on assets (ROA), net-income version = net income ÷ total assets × 100."}]},{"text":[{"text":"Return on capital employed (ROCE) = EBIT ÷ capital employed × 100."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Capital employed = total assets - current liabilities = equity + preference capital + long-term debt."}]}]}]},{"text":[{"text":"Return on shareholders' equity (ROSE or ROE) = EAIT (earnings after interest and tax) ÷ shareholders' equity × 100."}]}]},{"type":"table","header":[[{"text":"Abbreviation"}],[{"text":"Meaning"}]],"rows":[[[{"text":"EBIT"}],[{"text":"Earnings (profit) before interest and tax"}]],[[{"text":"EBT / PBT"}],[{"text":"Earnings (profit) before tax"}]],[[{"text":"EAIT / PAT"}],[{"text":"Earnings after interest and tax / profit after tax"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Moving between profit lines:","bold":true},{"text":" EBIT = PBT + interest. PAT = PBT × (1 - tax rate)."}]},{"text":[{"text":"Example (₦'000):","italic":true},{"text":" credit sales 40,000; PBT 6,000; interest on loan 8,000; total assets 54,000; tax rate 35%; shareholders' funds 160,000."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"PAT = 6,000 × 0.65 = 3,900. ROSE = 3,900 ÷ 160,000 × 100 = 2.44% = "},{"text":"2%","bold":true},{"text":" to the nearest whole number. (Using PBT wrongly gives 3.75%, about 4%.)"}]},{"text":[{"text":"EBIT = 6,000 + 8,000 = 14,000. ROTA = 14,000 ÷ 54,000 × 100 = 25.93% = "},{"text":"26%","bold":true},{"text":"."}]}]}]},{"text":[{"text":"Example:","italic":true},{"text":" sales ₦40,000, EBIT ₦9,000, total assets ₦54,900. ROTA = 9,000 ÷ 54,900 × 100 = "},{"text":"16.4%","bold":true},{"text":". With capital employed ₦100,900, ROCE = 9,000 ÷ 100,900 × 100 = "},{"text":"8.9%","bold":true},{"text":", about 9%."}]},{"text":[{"text":"Example:","italic":true},{"text":" sales ₦108,700, cost of sales ₦91,000. Gross profit = ₦17,700; margin = 17,700 ÷ 108,700 × 100 = "},{"text":"16.3%","bold":true},{"text":"."}]},{"text":[{"text":"A higher gross margin means efficient production and cost control; a higher ROA means better asset use; ROE measures "},{"text":"profit from shareholders' funds","bold":true},{"text":", so it is a profitability ratio (unlike the debt, current and quick ratios)."}]}]}]},{"number":"5.5","title":"Gearing (long-term solvency) and stock market ratios","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Gearing ratio = fixed interest capital ÷ equity capital","bold":true},{"text":" (x : 1)."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Fixed interest capital = debt capital + preference share capital."}]},{"text":[{"text":"Equity capital = ordinary share capital + share premium + revenue reserves + retained earnings."}]}]}]},{"text":[{"text":"Debt-to-equity ratio = total debt (or total liabilities) ÷ shareholders' equity."}]},{"text":[{"text":"Debt ratio = total debt ÷ total assets × 100, where total debt = current liabilities + long-term debt."}]},{"text":[{"text":"Fixed interest cover (interest coverage, times interest earned) = EBIT ÷ annual fixed interest charged on debt (times)."}]},{"text":[{"text":"Proprietary ratio = shareholders' equity ÷ total tangible assets × 100."}]},{"text":[{"text":"Stock market ratios:","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Dividend per share (DPS) = gross (ordinary) dividend ÷ number of ordinary shares issued and fully paid."}]},{"text":[{"text":"Earnings per share (EPS) = earnings after interest and tax (less preference dividend) ÷ number of ordinary shares issued and fully paid."}]},{"text":[{"text":"Dividend yield = DPS ÷ market price per share × 100."}]},{"text":[{"text":"Earnings yield = EPS ÷ market price per share × 100."}]},{"text":[{"text":"Price/earnings (P/E) ratio = market price per share ÷ EPS (times)."}]},{"text":[{"text":"Dividend cover = earnings available to ordinary shareholders ÷ ordinary dividend = EPS ÷ DPS","bold":true},{"text":" (times)."}]},{"text":[{"text":"Dividend payout ratio = DPS ÷ EPS × 100 (the reciprocal of dividen$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin101', 20, $study_guide$d cover)."}]},{"text":[{"text":"Price-to-book (P/B) = market price per share ÷ book value per share (book value per share = ordinary equity ÷ number of shares)."}]}]}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A "},{"text":"high debt-to-equity","bold":true},{"text":" (or gearing) ratio means "},{"text":"significant leverage","bold":true},{"text":": heavy reliance on debt, so higher financial risk. A lower debt ratio means a stronger position; a higher interest cover means interest is paid more easily."}]},{"text":[{"text":"Gearing example:","italic":true},{"text":" debt capital ₦130,000; preference capital ₦90,000; equity ₦658,700. Gearing = 220,000 ÷ 658,700 = "},{"text":"0.33:1","bold":true},{"text":"."}]},{"text":[{"text":"Debt ratio example:","italic":true},{"text":" current liabilities ₦13,650; long-term debt ₦5,400; total assets ₦87,000. Debt ratio = 19,050 ÷ 87,000 × 100 = "},{"text":"21.9%","bold":true},{"text":". Trap: add "},{"text":"both","bold":true},{"text":" kinds of debt; using current liabilities alone gives 15.7%."}]},{"text":[{"text":"DPS example:","italic":true},{"text":" gross dividend ₦108,700 on 900,000 shares. DPS = "},{"text":"₦0.12 (12 kobo)","bold":true},{"text":", to the nearest kobo."}]},{"text":[{"text":"Dividend yield example:","italic":true},{"text":" DPS ₦1.70, market price ₦11.45. Yield = 1.70 ÷ 11.45 × 100 = 14.8%, about "},{"text":"15%","bold":true},{"text":"."}]},{"text":[{"text":"EPS and P/E are inversely related:","bold":true},{"text":" for a given price, higher EPS means lower P/E. Earnings yield is P/E turned upside down. A "},{"text":"high P/E","bold":true},{"text":" signals "},{"text":"potential overvaluation","bold":true},{"text":", or strong growth expectations; a low P/E may mean undervaluation."}]},{"text":[{"text":"Dividend cover","bold":true},{"text":" shows how many times the ordinary dividend could be paid out of the year's earnings. Cover of 2 times means half of earnings is paid out and half retained; cover below 1 means part of the dividend comes from past reserves."}]},{"text":[{"text":"Earnings yield and dividend yield use the "},{"text":"market price","bold":true},{"text":", so they are "},{"text":"market value ratios","bold":true},{"text":"; gross profit margin and times interest earned are not."}]}]}]},{"number":"5.6","title":"One full worked set","mustKnow":[{"type":"paragraph","text":[{"text":"Adebayo Ltd, figures in ₦'000. Ordinary shares: 200,000 of ₦1 each. Market price per share ₦3.60. All sales are on credit. Opening inventory ₦40,000."}]},{"type":"table","header":[[{"text":"Statement of financial position at 31 December"}],[{"text":"₦'000"}]],"rows":[[[{"text":"Land and buildings"}],[{"text":"300"}]],[[{"text":"Plant and machinery"}],[{"text":"150"}]],[[{"text":"Non-current assets","bold":true}],[{"text":"450","bold":true}]],[[{"text":"Inventory"}],[{"text":"60"}]],[[{"text":"Trade receivables"}],[{"text":"50"}]],[[{"text":"Cash"}],[{"text":"40"}]],[[{"text":"Current assets","bold":true}],[{"text":"150","bold":true}]],[[{"text":"Total assets","bold":true}],[{"text":"600","bold":true}]],[[{"text":"Ordinary share capital"}],[{"text":"200"}]],[[{"text":"Share premium"}],[{"text":"50"}]],[[{"text":"Retained earnings"}],[{"text":"100"}]],[[{"text":"Ordinary shareholders' equity","bold":true}],[{"text":"350","bold":true}]],[[{"text":"10% preference share capital"}],[{"text":"50"}]],[[{"text":"10% debenture (long-term debt)"}],[{"text":"100"}]],[[{"text":"Trade payables"}],[{"text":"70"}]],[[{"text":"Tax payable"}],[{"text":"30"}]],[[{"text":"Current liabilities","bold":true}],[{"text":"100","bold":true}]],[[{"text":"Total equity and liabilities","bold":true}],[{"text":"600","bold":true}]]]},{"type":"table","header":[[{"text":"Income statement for the year"}],[{"text":"₦'000"}]],"rows":[[[{"text":"Sales"}],[{"text":"900"}]],[[{"text":"Cost of sales"}],[{"text":"(540)"}]],[[{"text":"Gross profit","bold":true}],[{"text":"360","bold":true}]],[[{"text":"Operating expenses"}],[{"text":"(240)"}]],[[{"text":"EBIT","bold":true}],[{"text":"120","bold":true}]],[[{"text":"Interest (10% × 100)"}],[{"text":"(10)"}]],[[{"text":"Profit before tax","bold":true}],[{"text":"110","bold":true}]],[[{"text":"Tax at 30%"}],[{"text":"(33)"}]],[[{"text":"Profit after tax (EAIT)","bold":true}],[{"text":"77","bold":true}]],[[{"text":"Preference dividend (10% × 50)"}],[{"text":"(5)"}]],[[{"text":"Earnings for ordinary shareholders","bold":true}],[{"text":"72","bold":true}]],[[{"text":"Ordinary dividend"}],[{"text":"(36)"}]],[[{"text":"Retained for the year","bold":true}],[{"text":"36","bold":true}]]]}],"explainMore":[{"type":"paragraph","text":[{"text":"Supporting figures: capital employed = 600 - 100 = 500 (also 350 + 50 + 100). Total debt = 100 + 100 = 200. Average inventory = (40 + 60) ÷ 2 = 50. Credit purchases = 540 + 60 - 40 = 560. Only closing receivables (50) are given, so they stand in for average receivables."}]},{"type":"table","header":[[{"text":"Ratio"}],[{"text":"Working"}],[{"text":"Result"}]],"rows":[[[{"text":"Current ratio"}],[{"text":"150 ÷ 100"}],[{"text":"1.5:1"}]],[[{"text":"Quick ratio"}],[{"text":"(150 - 60) ÷ 100"}],[{"text":"0.9:1"}]],[[{"text":"Cash ratio"}],[{"text":"40 ÷ 100"}],[{"text":"0.4:1"}]],[[{"text":"Working capital"}],[{"text":"150 - 100"}],[{"text":"₦50,000"}]],[[{"text":"Inventory turnover"}],[{"text":"540 ÷ 50"}],[{"text":"10.8 times"}]],[[{"text":"Inventory days"}],[{"text":"365 ÷ 10.8"}],[{"text":"33.8 days"}]],[[{"text":"Receivables turnover"}],[{"text":"900 ÷ 50"}],[{"text":"18 times"}]],[[{"text":"Collection period"}],[{"text":"50 ÷ 900 × 365"}],[{"text":"20.3 days"}]],[[{"text":"Payment period"}],[{"text":"70 ÷ 560 × 365"}],[{"text":"45.6 days"}]],[[{"text":"Asset turnover"}],[{"text":"900 ÷ 600"}],[{"text":"1.5 times"}]],[[{"text":"Gross profit margin"}],[{"text":"360 ÷ 900 × 100"}],[{"text":"40%"}]],[[{"text":"Operating (EBIT) margin"}],[{"text":"120 ÷ 900 × 100"}],[{"text":$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin101', 21, $study_guide$"13.3%"}]],[[{"text":"Net profit margin"}],[{"text":"77 ÷ 900 × 100"}],[{"text":"8.6%"}]],[[{"text":"ROTA"}],[{"text":"120 ÷ 600 × 100"}],[{"text":"20%"}]],[[{"text":"ROA (net income)"}],[{"text":"77 ÷ 600 × 100"}],[{"text":"12.8%"}]],[[{"text":"ROCE"}],[{"text":"120 ÷ 500 × 100"}],[{"text":"24%"}]],[[{"text":"ROSE / ROE"}],[{"text":"77 ÷ 350 × 100"}],[{"text":"22%"}]],[[{"text":"Gearing"}],[{"text":"(100 + 50) ÷ 350"}],[{"text":"0.43:1"}]],[[{"text":"Debt-to-equity"}],[{"text":"200 ÷ 350"}],[{"text":"0.57:1"}]],[[{"text":"Debt ratio"}],[{"text":"200 ÷ 600 × 100"}],[{"text":"33.3%"}]],[[{"text":"Interest cover"}],[{"text":"120 ÷ 10"}],[{"text":"12 times"}]],[[{"text":"Proprietary ratio"}],[{"text":"350 ÷ 600 × 100"}],[{"text":"58.3%"}]],[[{"text":"EPS"}],[{"text":"₦72,000 ÷ 200,000"}],[{"text":"₦0.36"}]],[[{"text":"DPS"}],[{"text":"₦36,000 ÷ 200,000"}],[{"text":"₦0.18"}]],[[{"text":"P/E ratio"}],[{"text":"3.60 ÷ 0.36"}],[{"text":"10 times"}]],[[{"text":"Earnings yield"}],[{"text":"0.36 ÷ 3.60 × 100"}],[{"text":"10%"}]],[[{"text":"Dividend yield"}],[{"text":"0.18 ÷ 3.60 × 100"}],[{"text":"5%"}]],[[{"text":"Dividend cover"}],[{"text":"72 ÷ 36 (= 0.36 ÷ 0.18)"}],[{"text":"2 times"}]],[[{"text":"Payout ratio"}],[{"text":"0.18 ÷ 0.36 × 100"}],[{"text":"50%"}]],[[{"text":"Book value per share"}],[{"text":"₦350,000 ÷ 200,000"}],[{"text":"₦1.75"}]],[[{"text":"P/B ratio"}],[{"text":"3.60 ÷ 1.75"}],[{"text":"2.06 times"}]]]},{"type":"paragraph","text":[{"text":"Rounding: days and percentages to 1 d.p., P/B, gearing and debt-to-equity to 2 d.p."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Reading the results:","bold":true},{"text":" the current ratio (1.5:1) and quick ratio (0.9:1) are below the 2:1 and 1:1 ideals, so liquidity is a little tight. Interest cover of 12 times and gearing of 0.43:1 show modest borrowing. ROCE of 24% is healthy."}]},{"text":[{"text":"Traps in this set:","bold":true},{"text":" EPS uses earnings "},{"text":"after","bold":true},{"text":" the preference dividend (72, not 77). Dividend cover uses the "},{"text":"ordinary","bold":true},{"text":" dividend only. ROCE uses capital employed (500), ROTA uses total assets (600). If a question says \"total debt ÷ equity\" use 200; if it says \"long-term debt ÷ equity\" use 100 ÷ 350 = 0.29:1. Some questions compute ROE from earnings for ordinary shareholders: 72 ÷ 350 × 100 = 20.6%. Always follow the formula the question states."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Statement of financial position = one date; income statement = performance over a period; cash flow statement = 3 sections (operating, investing, financing)."}]},{"text":[{"text":"Current liabilities fall due within 1 year; land is a fixed asset; working capital = CA - CL."}]},{"text":[{"text":"10 users of ratios; management is internal; debtors are not users; analysts advise clients."}]},{"text":[{"text":"4 groups: liquidity (short-term solvency), efficiency and profitability, stability (long-term solvency), stock market."}]},{"text":[{"text":"Current ratio ideal 2:1; quick ratio ideal 1:1 and excludes inventory."}]},{"text":[{"text":"Stock turnover = cost of sales ÷ average stock; collection period = debtors ÷ credit sales × 365; payment period = creditors ÷ credit purchases × 365."}]},{"text":[{"text":"ROTA = EBIT ÷ total assets; ROCE = EBIT ÷ capital employed; ROSE = EAIT ÷ equity."}]},{"text":[{"text":"Gearing = (debt + preference capital) ÷ equity; debt ratio = (CL + long-term debt) ÷ total assets; interest cover = EBIT ÷ interest."}]},{"text":[{"text":"EPS, DPS, dividend yield, earnings yield, P/E (inverse of EPS), dividend cover = EPS ÷ DPS."}]},{"text":[{"text":"Ratios are easy and comparable, but alone tell little, are easily misread and do not show causes."}]}]}],"theory":{"itemId":"58b6d20d-4ef2-5fc4-b6eb-9cbf882aaaa7","question":[{"type":"paragraph","text":[{"text":"Bode Plc earned profit after tax of ₦4,800,000 and paid a preference dividend of ₦800,000 and an ordinary dividend of ₦1,600,000. It has 10,000,000 ordinary shares priced at ₦4.00 each. Calculate EPS, DPS, dividend cover, P/E ratio and dividend yield."}]}]},"practice":[{"topic":"Financial Statement and Ratio Analysis","named":false}]}},{"kind":"note","itemId":"51fe3ef0-f55f-5398-8aa8-ef58bb70fe89","sourceKey":"guide-topic:6","position":6,"payload":{"title":"Introduction to Financial Markets","body":"The financial system and the meaning, functions and types of financial markets; money market vs capital market and their instruments; primary vs secondary markets; the Nigerian stock market; participants, institutions and regulators (CBN, SEC, NGX); short-, medium- and long-term sources of finance with their merits and demerits.","noteType":"guide_topic","number":6,"mustKnow":[{"text":"The financial system and the meaning, functions and types of financial markets; money market vs capital market and their instruments; primary vs secondary markets; the Nigerian stock market; participants, institutions and regulators (CBN, SEC, NGX); short-, medium- and long-term sources of finance with their merits and demerits."}],"lessons":[{"number":"6.1","title":"The financial system and financial markets","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Financial system:","bold":true},{"text":" a complex of "},{"text":"institutions, instruments, rules and regulations","bold":true},{"text":" that facilitates the "},{"text":"mobilisation and transfer of resources from savings-surplus units to deficit units","bold":true},{"text":"."}]},{"text":[{"text":"Financial market:","bold":true},{"text":" a marketplace where buyers and sellers "},{"text":"trade financial assets","bold":true},{"text":" such as stocks, bonds, currencies, derivatives and commodities. It facilitates the flow of funds between investors, businesses and governments, mobilising capital, managing risk and allocating resources efficiently."}]},{"text":[{"text":"Other definitions: $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin101', 22, $study_guide$any system or structure that makes it possible to trade in different kinds of financial securities; markets where debt, debentures and equities are traded; markets where funds can be raised."}]},{"text":[{"text":"A financial market brings together "},{"text":"those who have money","bold":true},{"text":" (lenders, buyers of financial instruments) and "},{"text":"those who need money","bold":true},{"text":" (borrowers, sellers of financial instruments). Without it, borrowers would find it difficult to locate lenders."}]},{"text":[{"text":"Financial security (instrument):","bold":true},{"text":" the receipt the borrower issues to the lender as a promise or evidence to pay back the capital. It is a tradeable claim to money or ownership: a share, bond, treasury bill."}]},{"text":[{"text":"Financial asset:","bold":true},{"text":" a claim to money: "},{"text":"cash","bold":true},{"text":", shares, bonds, deposits. "},{"text":"Real (physical) assets:","bold":true},{"text":" machinery, buildings, factories, inventory."}]}]},{"type":"paragraph","text":[{"text":"7 functions of financial markets:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Capital formation:","bold":true},{"text":" raising capital by issuing stocks and bonds."}]},{"text":[{"text":"Liquidity provision:","bold":true},{"text":" assets can be converted to cash without significant loss in value."}]},{"text":[{"text":"Efficient price discovery:","bold":true},{"text":" prices are set by "},{"text":"supply and demand","bold":true},{"text":", reflecting available information."}]},{"text":[{"text":"Risk management:","bold":true},{"text":" derivatives hedge price, interest-rate and currency risks."}]},{"text":[{"text":"Facilitating savings and investment.","bold":true}]},{"text":[{"text":"Economic growth:","bold":true},{"text":" capital flows to the projects with the highest potential."}]},{"text":[{"text":"Reducing transaction costs:","bold":true},{"text":" trading is centralised."}]}]},{"type":"paragraph","text":[{"text":"6 types of financial markets:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Capital markets:","bold":true},{"text":" long-term instruments (stocks, bonds); split into primary and secondary."}]},{"text":[{"text":"Money markets:","bold":true},{"text":" short-term instruments (maturity "},{"text":"less than one year","bold":true},{"text":")."}]},{"text":[{"text":"Foreign exchange (forex) markets:","bold":true},{"text":" trading currencies."}]},{"text":[{"text":"Derivatives markets:","bold":true},{"text":" futures, options, swaps."}]},{"text":[{"text":"Commodity markets:","bold":true},{"text":" metals, energy, agricultural products."}]},{"text":[{"text":"Cryptocurrency markets:","bold":true},{"text":" Bitcoin, Ethereum and others."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"In short: financial markets "},{"text":"enable funds to move efficiently","bold":true},{"text":" from savers to users. They do not curtail competition, raise production costs or restrict investment choice."}]},{"text":[{"text":"Trap: a factory, machine or office building is a "},{"text":"real asset","bold":true},{"text":", not a financial instrument. "},{"text":"Accounts payable","bold":true},{"text":" is a liability, not an asset. Cash "},{"text":"is","bold":true},{"text":" a financial asset."}]},{"text":[{"text":"Trap: \"savings market\" or \"economic system\" are distractors for the definition of the "},{"text":"financial system","bold":true},{"text":"."}]},{"text":[{"text":"The narrow two-way split (money market and capital market) is the one most questions use; the six-way list adds forex, derivatives, commodity and crypto markets."}]}]}]},{"number":"6.2","title":"Money market vs capital market","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Money market:","bold":true},{"text":" where "},{"text":"short-term","bold":true},{"text":" financial securities are bought and sold. Funds raised can be used for a "},{"text":"maximum of one year or less","bold":true},{"text":"."}]},{"text":[{"text":"Capital market:","bold":true},{"text":" where securities with a life span of "},{"text":"more than one year","bold":true},{"text":" are bought and sold; the market for "},{"text":"medium- and long-term","bold":true},{"text":" funds (long-term borrowing and lending)."}]}]},{"type":"paragraph","text":[{"text":"Functions of the money market (5):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Promotes economic growth by making money available to different sectors."}]},{"text":[{"text":"Platform for effective implementation of "},{"text":"monetary policy","bold":true},{"text":"."}]},{"text":[{"text":"Stabilises demand and supply of money for short-term transactions."}]},{"text":[{"text":"Avenue for short-term investment."}]},{"text":[{"text":"Generates savings and investment in the economy."}]}]},{"type":"paragraph","text":[{"text":"Money market instruments:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Treasury bills:","bold":true},{"text":" used by government to borrow for a short time; issued by the "},{"text":"Central Bank","bold":true},{"text":" (on behalf of government); maturity under one year."}]},{"text":[{"text":"Repurchase agreements (repos):","bold":true},{"text":" the seller sells a security to the buyer and agrees to "},{"text":"buy the same security back","bold":true},{"text":" later."}]},{"text":[{"text":"Certificate of deposit:","bold":true},{"text":" a promissory note issued by a "},{"text":"bank","bold":true},{"text":" giving the bearer the right to receive interest."}]},{"text":[{"text":"Banker's acceptance:","bold":true},{"text":" a promise by the buyer to pay the seller, with the "},{"text":"buyer's bank standing as guarantor","bold":true},{"text":"."}]},{"text":[{"text":"Commercial paper:","bold":true},{"text":" short-term "},{"text":"unsecured pro$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin101', 23, $study_guide$missory note","bold":true},{"text":" issued by large, creditworthy ("},{"text":"blue-chip","bold":true},{"text":") companies, backed only by the issuer's promise to pay the face value at maturity."}]},{"text":[{"text":"Call money:","bold":true},{"text":" very short-term lending between banks, repayable on call. "},{"text":"Bank deposits","bold":true},{"text":" are also money market instruments."}]}]},{"type":"paragraph","text":[{"text":"Capital market instruments:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Ordinary shares (equities, common stock):","bold":true},{"text":" part ownership; each member is a fractional owner bearing the maximum entrepreneurial risk; voting rights and dividends."}]},{"text":[{"text":"Preference shares:","bold":true},{"text":" fixed dividends, usually no voting rights."}]},{"text":[{"text":"Bonds:","bold":true},{"text":" long-term debt issued by companies or governments, paying fixed interest and "},{"text":"redeemable","bold":true},{"text":" at maturity."}]},{"text":[{"text":"Debentures (debenture stock):","bold":true},{"text":" debt instruments issued by companies to raise capital. The basic (naked) debenture is "},{"text":"not secured","bold":true},{"text":" by physical assets; it promises interest and principal, and holders become "},{"text":"creditors","bold":true},{"text":" of the company."}]}]},{"type":"table","header":[[{"text":"Point"}],[{"text":"Money market"}],[{"text":"Capital market"}]],"rows":[[[{"text":"Maturity"}],[{"text":"One year or less"}],[{"text":"More than one year"}]],[[{"text":"Purpose"}],[{"text":"Working capital, short-term needs"}],[{"text":"Long-term investment"}]],[[{"text":"Instruments"}],[{"text":"T-bills, CP, CDs, BAs, repos, call money"}],[{"text":"Shares, bonds, debentures"}]],[[{"text":"Apex regulator in Nigeria"}],[{"text":"CBN","bold":true}],[{"text":"SEC","bold":true}]]]},{"type":"paragraph","text":[{"text":"Other instruments:","bold":true},{"text":" derivatives ("},{"text":"futures","bold":true},{"text":": agreement to buy or sell at a set price on a future date; "},{"text":"options","bold":true},{"text":": the right but not the obligation to buy or sell before expiry; "},{"text":"swaps","bold":true},{"text":": exchange of cash flows); forex (spot, forward, currency swaps); commodity contracts; cryptocurrencies."}]},{"type":"paragraph","text":[{"text":"Treasury bill pricing (discount basis, 365-day year):","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Discount = Face value × discount rate × days / 365"}]},{"text":[{"text":"Price = Face value − Discount"}]},{"text":[{"text":"Yield = (Discount / Price) × (365 / days)"}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Worked example.","bold":true},{"text":" A 91-day treasury bill has a face value of ₦1,000,000 and a discount rate of 18% a year."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Discount = 1,000,000 × 0.18 × 91 / 365 = "},{"text":"₦44,876.71","bold":true}]},{"text":[{"text":"Price = 1,000,000 − 44,876.71 = "},{"text":"₦955,123.29","bold":true}]},{"text":[{"text":"Yield = (44,876.71 / 955,123.29) × (365 / 91) = "},{"text":"18.85%","bold":true},{"text":" (to 2 d.p.). The yield is above the discount rate because you earn the discount on ₦955,123.29, not on ₦1,000,000."}]}]}]},{"text":[{"text":"Nigerian T-bills run for 91, 182 or 364 days. They pay no coupon; you buy below face value and receive the full face value at maturity."}]},{"text":[{"text":"Traps: \"the stock market\" is a "},{"text":"long-term capital market","bold":true},{"text":", not a short-term lending market. Debenture stock and preference shares are "},{"text":"capital market","bold":true},{"text":"; bankers' acceptances, commercial paper and bank deposits are "},{"text":"money market","bold":true},{"text":"."}]},{"text":[{"text":"A "},{"text":"bond","bold":true},{"text":" is debt (you lend); a "},{"text":"stock","bold":true},{"text":" is ownership (you own). A certificate of deposit and a loan are also debt."}]}]}]},{"number":"6.3","title":"Primary vs secondary markets and the stock market","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Primary market:","bold":true},{"text":" where "},{"text":"new","bold":true},{"text":" securities are issued and sold to investors "},{"text":"for the first time","bold":true},{"text":" (e.g. IPOs). Transactions are between the "},{"text":"issuing company and investors","bold":true},{"text":"; the issuer gets the money."}]},{"text":[{"text":"Secondary market:","bold":true},{"text":" where "},{"text":"already issued","bold":true},{"text":" securities are traded among investors. The "},{"text":"issuing company is not involved","bold":true},{"text":"."}]},{"text":[{"text":"Stock market:","bold":true},{"text":" the segment of the financial market where equities and other securities are issued, bought and sold. In Nigeria it is regulated by the "},{"text":"SEC","bold":true},{"text":" and facilitated by the "},{"text":"Nigerian Exchange Group (NGX)","bold":true},{"text":", formerly the Nigerian Stock Exchange (NSE)."}]},{"text":[{"text":"Stock exchange:","bold":true},{"text":" its major role is to "},{"text":"facilitate the trading of securities","bold":true},{"text":" in an organised market."}]}]},{"type":"paragraph","text":[{"text":"Primary market functions in Nigeria (7):","bold":true},{"text":" capital formation; facilitates economic growth; investment opportunities; promotes industrialisation; government fundraising (FGN bonds); encourages entrepreneurship; price determination (sets the initial price). "},{"text":"Importance:","bold":true},{"text":" boosts financial inclusion; supports public-private partnerships; stimulates foreign investment."}]},{"type":"paragraph","text":[{"text":"Secondary market functions (8):","bold":true},{"text":" liquidity provision; continuous price discovery; portfolio diversification; encourages inv$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin101', 24, $study_guide$estment; capital reallocation; wealth creation (capital gains, dividends, interest); supports the primary market (assures buyers they can sell later); regulatory oversight by SEC and NGX. "},{"text":"Importance:","bold":true},{"text":" market confidence; foreign participation; stimulates economic growth; wealth redistribution; enables corporate governance."}]},{"type":"paragraph","text":[{"text":"Importance of the stock market in Nigeria (10):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Capital formation"}]},{"text":[{"text":"Economic growth (adds to GDP)"}]},{"text":[{"text":"Wealth creation"}]},{"text":[{"text":"Encourages savings and investment"}]},{"text":[{"text":"Liquidity provision"}]},{"text":[{"text":"Promotes corporate governance"}]},{"text":[{"text":"Employment generation (brokers, analysts, fund managers)"}]},{"text":[{"text":"Attracts foreign investment"}]},{"text":[{"text":"Supports government financing"}]},{"text":[{"text":"Risk diversification"}]}]},{"type":"paragraph","text":[{"text":"Functions of the stock market (9):","bold":true},{"text":" mobilisation of savings; facilitating capital raising (IPOs, bonds); providing liquidity; price discovery; enhancing corporate governance; "},{"text":"economic indicator","bold":true},{"text":" (barometer of economic health); risk management; wealth redistribution; investment opportunities."}]},{"type":"paragraph","text":[{"text":"Instruments traded on the Nigerian stock market (8):","bold":true},{"text":" equities (ordinary and preference shares); debt (corporate and government bonds); "},{"text":"ETFs","bold":true},{"text":"; derivatives; "},{"text":"mutual funds","bold":true},{"text":"; "},{"text":"REITs","bold":true},{"text":" (returns from real estate); commercial papers; "},{"text":"GDRs","bold":true},{"text":" (let Nigerian companies trade shares on foreign exchanges)."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Memory hook: "},{"text":"primary = first sale, money to the company; secondary = resale, money between investors.","bold":true},{"text":" \"Tertiary market\" is a distractor. Where \"primary market\" is an option, pick it over the broader \"capital market\" for new issues."}]},{"text":[{"text":"Share prices are set by "},{"text":"market supply and demand","bold":true},{"text":", not by government, wages or production costs."}]},{"text":[{"text":"Mutual fund:","bold":true},{"text":" a "},{"text":"collective investment pool","bold":true},{"text":" of many investors' money, professionally managed and spread over many securities."}]},{"text":[{"text":"In 2021 the Nigerian Stock Exchange was demutualised into the Nigerian Exchange Group; questions may still say \"NSE\"."}]}]}]},{"number":"6.4","title":"Participants, institutions and regulators","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Financial intermediary:","bold":true},{"text":" a "},{"text":"link between lenders and borrowers","bold":true},{"text":" (savers and users of funds): banks, mutual funds, hedge funds, investment firms."}]},{"text":[{"text":"Financial institutions","bold":true},{"text":" deal in money and financial services: commercial (deposit money) banks, stock exchanges, insurance companies, pension funds. A "},{"text":"supermarket is not one","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"10 participants in financial markets:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Investors:","bold":true},{"text":" supply funds to earn returns (pension funds, insurers)."}]},{"text":[{"text":"Issuers:","bold":true},{"text":" governments and corporations raising capital."}]},{"text":[{"text":"Brokers and dealers:","bold":true},{"text":" brokers act for others for a commission; dealers trade on their own account."}]},{"text":[{"text":"Regulatory bodies:","bold":true},{"text":" e.g. SEC (US), RBI (India), FCA (UK)."}]},{"text":[{"text":"Financial intermediaries.","bold":true}]},{"text":[{"text":"Speculators:","bold":true},{"text":" profit from price movements."}]},{"text":[{"text":"Hedgers:","bold":true},{"text":" use instruments to manage risk."}]},{"text":[{"text":"Arbitrageurs:","bold":true},{"text":" exploit price differences for risk-free profit."}]},{"text":[{"text":"Central banks:","bold":true},{"text":" monetary policy, liquidity, interest rates."}]},{"text":[{"text":"Rating agencies:","bold":true},{"text":" S&P, Moody's, Fitch rate creditworthiness."}]}]},{"type":"paragraph","text":[{"text":"Participants in the Nigerian stock market (10):","bold":true},{"text":" investors (retail, mutual funds, pension funds); issuers; "},{"text":"stockbrokers","bold":true},{"text":" (licensed agents); "},{"text":"NGX","bold":true},{"text":" (platform for listing and trading); "},{"text":"SEC","bold":true},{"text":" (regulator); "},{"text":"market makers","bold":true},{"text":" (keep liquidity, stabilise prices); "},{"text":"investment banks","bold":true},{"text":" (issuing houses: help issue securities, advise); fund managers; foreign investors; clearing and settlement institutions ("},{"text":"CSCS","bold":true},{"text":", Central Securities Clearing System)."}]},{"type":"table","header":[[{"text":"Body"}],[{"text":"Role"}]],"rows":[[[{"text":"CBN","bold":true}],[{"text":"Apex regulator of the "},{"text":"money market","bold":true},{"text":" and banks; monetary policy; issues T-bills"}]],[[{"text":"SEC","bold":true}],[{"text":"Apex regulator of the "},{"text":"capital market","bold":true}]],[[{"text":"NGX","bold":true}],[{"text":"Exchange where securities are listed and traded"}]],[[{"text":"NDIC","bold":true}],[{"text":"Insures bank deposits"}]],[[{"text":"NAICOM","bold":true}],[{"text":"Regulates insurance"}]],[[{"text":"PenCom","bold":true}],[{"text":"Regulates pensions"}]],[[{"text":"Deposit money banks","bold":true}],[{"text":"Take deposits, lend, run overdrafts"}]]]}],"explainMore":[{"type":"list","ordered":false$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin101', 25, $study_guide$,"items":[{"text":[{"text":"Traps: CBN vs SEC is the most swapped pair. "},{"text":"Money market → CBN; capital market → SEC.","bold":true},{"text":" The NGX is a market, not the apex regulator; issuing houses help companies raise capital."}]},{"text":[{"text":"Insurance companies and pension funds are major "},{"text":"institutional investors","bold":true},{"text":": they collect premiums and contributions and invest them in bonds, shares and T-bills."}]},{"text":[{"text":"Factories, shops and workers belong to goods and labour markets; "},{"text":"investors","bold":true},{"text":" are the financial market participants."}]}]}]},{"number":"6.5","title":"Sources of finance and financing business","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Classify by "},{"text":"how long","bold":true},{"text":" the funds are kept: "},{"text":"short-term","bold":true},{"text":" (within one year), "},{"text":"medium-term","bold":true},{"text":" (about one to five years), "},{"text":"long-term","bold":true},{"text":" (beyond five years, or permanent)."}]},{"text":[{"text":"Internal source:","bold":true},{"text":" "},{"text":"retained earnings","bold":true},{"text":" (net income reinvested in the business instead of being paid as dividends). Everything else here is "},{"text":"external","bold":true},{"text":"."}]},{"text":[{"text":"Equity finance","bold":true},{"text":" = "},{"text":"ownership capital","bold":true},{"text":" (from owners: shares, retained earnings). "},{"text":"Debt finance","bold":true},{"text":" = loan capital (borrowed: loans, debentures, bonds)."}]},{"text":[{"text":"Matching principle:","bold":true},{"text":" finance short-term needs (working capital) with short-term sources and long-term assets with long-term sources."}]}]},{"type":"table","header":[[{"text":"Term"}],[{"text":"Source"}],[{"text":"Advantages"}],[{"text":"Disadvantages"}]],"rows":[[[{"text":"Short"}],[{"text":"Trade credit:","bold":true},{"text":" buy now, pay suppliers later"}],[{"text":"Easy, usually no interest"}],[{"text":"Lose cash discounts; supplier goodwill at risk"}]],[[{"text":"Short"}],[{"text":"Bank overdraft:","bold":true},{"text":" draw beyond the current account balance up to a limit"}],[{"text":"Flexible; interest only on amount used"}],[{"text":"Repayable on demand; high interest"}]],[[{"text":"Short"}],[{"text":"Factoring:","bold":true},{"text":" sell receivables to a factor for immediate cash"}],[{"text":"Quick cash; factor collects debts"}],[{"text":"Fees; customers may see it as weakness"}]],[[{"text":"Short"}],[{"text":"Commercial paper","bold":true}],[{"text":"Cheaper than bank loans; unsecured"}],[{"text":"Only for blue-chip firms"}]],[[{"text":"Short"}],[{"text":"Bill finance:","bold":true},{"text":" discounting bills of exchange, bankers' acceptances"}],[{"text":"Cash before the bill matures"}],[{"text":"Discount cost"}]],[[{"text":"Medium"}],[{"text":"Term loan:","bold":true},{"text":" fixed amount, fixed period, scheduled repayment"}],[{"text":"Certain, planned; interest is tax-deductible"}],[{"text":"Interest must be paid; often secured"}]],[[{"text":"Medium"}],[{"text":"Hire purchase:","bold":true},{"text":" pay by instalments; ownership passes after the "},{"text":"last","bold":true},{"text":" instalment"}],[{"text":"Use the asset at once"}],[{"text":"Costly; asset repossessed if you default"}]],[[{"text":"Medium"}],[{"text":"Leasing:","bold":true},{"text":" pay rentals to use an asset owned by the "},{"text":"lessor","bold":true}],[{"text":"No large outlay; rentals tax-deductible"}],[{"text":"No ownership; total cost high"}]],[[{"text":"Long"}],[{"text":"Ordinary shares","bold":true}],[{"text":"No obligation to repay; no fixed dividend"}],[{"text":"Dilutes control","bold":true},{"text":"; dividends not tax-deductible; issue costs"}]],[[{"text":"Long"}],[{"text":"Preference shares:","bold":true},{"text":" fixed dividend, priority over ordinary shares"}],[{"text":"No vote, so no loss of control"}],[{"text":"Fixed dividend, not tax-deductible"}]],[[{"text":"Long"}],[{"text":"Debentures","bold":true}],[{"text":"No loss of control; interest tax-deductible"}],[{"text":"Fixed interest and repayment; raises gearing"}]],[[{"text":"Long"}],[{"text":"Retained earnings","bold":true}],[{"text":"No issue cost, no dilution, no interest"}],[{"text":"Limited by profit; shareholders forgo dividends"}]]]},{"type":"paragraph","text":[{"text":"Equity vs debt:","bold":true}]},{"type":"table","header":[[{"text":"Point"}],[{"text":"Equity"}],[{"text":"Debt"}]],"rows":[[[{"text":"Holder is"}],[{"text":"Owner"}],[{"text":"Creditor (lender)"}]],[[{"text":"Return"}],[{"text":"Dividend (not compulsory)"}],[{"text":"Interest (legal obligation)"}]],[[{"text":"Repayment"}],[{"text":"None"}],[{"text":"At maturity"}]],[[{"text":"Tax"}],[{"text":"Dividends not deductible"}],[{"text":"Interest "},{"text":"tax-deductible","bold":true}]],[[{"text":"Control"}],[{"text":"Dilutes control"}],[{"text":"No dilution"}]]]},{"type":"paragraph","text":[{"text":"Factors in choosing a source:","bold":true},{"text":" cost, period (purpose) of need, control, risk and gearing, security available, flexibility, size of the firm."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Factoring example.","bold":true},{"text":" A firm has ₦2,000,000 of receivables. The factor advances 80% at once and charges a 2% fee. Advance = 0.80 × 2,000,000 = "},{"text":"₦1,600,000","bold":true},{"text":". Fee = 0.02 × 2,000,000 = "},{"text":"₦40,000","bold":true},{"text":". The firm gets cash today instead of waiting for customers."}]},{"text":[{"text":"Leasing","bold":true},{"text":" is medium- to long-term, not short-term: it is the odd one out among factoring, bill finance and trade credit."}]},{"text":[{"text":"Bonds","bold":true},{"text":" and debentures are long-term; a "},{"text":"bank loan","bold":true},{"text":" is usually short- or medium-term. Where \"debenture\" is an option for long-term finance, $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin101', 26, $study_guide$it is the safe choice."}]},{"text":[{"text":"Advantage of equity: "},{"text":"no obligation to repay","bold":true},{"text":". Tax-deductible interest is an advantage of "},{"text":"debt","bold":true},{"text":"; diluting control is a "},{"text":"disadvantage","bold":true},{"text":" of equity."}]},{"text":[{"text":"Equity security","bold":true},{"text":" = "},{"text":"ordinary share","bold":true},{"text":". Preference shares and convertibles are hybrids; debenture stock is pure debt."}]},{"text":[{"text":"Hire purchase vs leasing:","bold":true},{"text":" under HP you eventually "},{"text":"own","bold":true},{"text":" the asset; under a lease the lessor keeps ownership."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Financial system = institutions, instruments, rules and regulations moving funds from surplus to deficit units."}]},{"text":[{"text":"Financial markets: capital formation, liquidity, price discovery, risk management, savings, growth, lower transaction costs."}]},{"text":[{"text":"Money market: one year or less (T-bills, CP, CDs, BAs, repos); capital market: over one year (shares, bonds, debentures)."}]},{"text":[{"text":"Primary = new issues, money to the issuer; secondary = existing securities between investors."}]},{"text":[{"text":"CBN = apex money market regulator; SEC = apex capital market regulator; NGX = the exchange."}]},{"text":[{"text":"Financial intermediary links lenders and borrowers; mutual fund = collective investment pool."}]},{"text":[{"text":"Short-term: trade credit, overdraft, factoring, CP, bill finance. Medium: term loans, HP, leasing. Long: ordinary and preference shares, debentures, retained earnings."}]},{"text":[{"text":"Equity = ownership capital, never repaid; debt interest is tax-deductible."}]}]}],"theory":{"itemId":"f744b4e0-a23a-576b-aef7-06a24f544785","question":[{"type":"paragraph","text":[{"text":"A supplier invoices ₦500,000 on terms of 2% discount if paid within 10 days, otherwise full payment in 30 days. What is the approximate annual cost of using the trade credit (giving up the discount)?"}]}]},"practice":[{"topic":"Introduction to Financial Markets","named":false}]}},{"kind":"note","itemId":"b7fdd21a-6dd9-531f-8144-8540051558b5","sourceKey":"guide-topic:7","position":7,"payload":{"title":"Forms of Business Firm","body":"The sole proprietorship, partnership, limited liability company (private and public), cooperative and public corporation: the definition, types, advantages, disadvantages and sources of funds of each; limited liability and the corporate form; how to choose a form of business.","noteType":"guide_topic","number":7,"mustKnow":[{"text":"The sole proprietorship, partnership, limited liability company (private and public), cooperative and public corporation: the definition, types, advantages, disadvantages and sources of funds of each; limited liability and the corporate form; how to choose a form of business."}],"lessons":[{"number":"7.1","title":"Sole proprietorship","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Sole proprietor:","bold":true},{"text":" someone who owns an "},{"text":"unincorporated","bold":true},{"text":" business by himself or herself. A sole proprietorship is the type of business organisation "},{"text":"owned, managed and controlled by a single owner","bold":true},{"text":". \"Sole\" means "},{"text":"only","bold":true},{"text":"; \"proprietor\" means "},{"text":"owner","bold":true},{"text":". Also called a "},{"text":"sole trader","bold":true},{"text":"."}]},{"text":[{"text":"Key features:","bold":true},{"text":" one owner; "},{"text":"unlimited liability","bold":true},{"text":"; "},{"text":"no separate legal personality","bold":true},{"text":"; few formalities; owner takes all profit and bears all loss; profit taxed as the owner's "},{"text":"personal income","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"5 types of sole proprietorship:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Service-based"}]},{"text":[{"text":"Retail-based"}]},{"text":[{"text":"Technology"}]},{"text":[{"text":"Manufacturing-based"}]},{"text":[{"text":"Consulting-based"}]}]},{"type":"paragraph","text":[{"text":"8 advantages:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Complete control and greater flexibility"}]},{"text":[{"text":"Easy set-up"}]},{"text":[{"text":"Low registration and start-up costs"}]},{"text":[{"text":"Lower accounting fees"}]},{"text":[{"text":"Greater privacy"}]},{"text":[{"text":"No sharing of profits (although the owner also carries any debt alone)"}]},{"text":[{"text":"Less paperwork"}]},{"text":[{"text":"Simplified taxes"}]}]},{"type":"paragraph","text":[{"text":"7 disadvantages:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Unlimited liability"}]},{"text":[{"text":"Potential credibility issues"}]},{"text":[{"text":"Sole responsibility"}]},{"text":[{"text":"Fewer tax planning opportunities"}]},{"text":[{"text":"Barriers to finance"}]},{"text":[{"text":"Sale limitations"}]},{"text":[{"text":"Limited expertise"}]}]},{"type":"paragraph","text":[{"text":"Sources of funds:","bold":true},{"text":" owner's personal savings; loans from family and friends; bank loans and overdrafts; microfinance bank and cooperative loans; trade (suppliers') credit; hire purchase; equipment leasing; ploughed-back profits. "},{"text":"Not","bold":true},{"text":" issue of shares or debentures."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Unlimited liability","bold":true},{"text":" means the owner's personal property (house, car, savings) can be taken to pay business debts. If Bisi's provision shop owes ₦8,000,000 and the shop's assets fetch only ₦5,000,000, creditors can recover the shortfall of 8,000,000 − 5,000,000 = "},{"text":"₦3,000,000","bold":true},{"text":" from Bisi personally."}]},{"text":[{"text":"Easy to form $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin101', 27, $study_guide$because it has few legal hurdles.","bold":true},{"text":" In Nigeria the owner usually just registers a "},{"text":"business name","bold":true},{"text":" with the "},{"text":"Corporate Affairs Commission (CAC)","bold":true},{"text":" and starts trading. No state charter, co-owners or shares are needed."}]},{"text":[{"text":"It ends when the owner dies or shuts it down.","bold":true},{"text":" Having no separate legal existence, it has no perpetual succession. Rapid growth does not end it; selling shares to the public or admitting partners would turn it into a different form."}]},{"text":[{"text":"Total owner control","bold":true},{"text":" is the classic advantage; "},{"text":"unlimited liability","bold":true},{"text":" is the classic disadvantage and the classic characteristic. Limited liability, legal personality and separate taxation belong to companies, not to sole traders."}]},{"text":[{"text":"\"Sale limitations\": the business is hard to sell, as its value is tied to the owner. \"Credibility issues\": banks and big customers may trust a one-person firm less."}]}]}]},{"number":"7.2","title":"Partnership","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Partnership:","bold":true},{"text":" a legal arrangement that allows "},{"text":"two or more people","bold":true},{"text":" to share responsibility for a business. Partners share the ownership and profits, and also the work, responsibility and potential losses."}]},{"text":[{"text":"Legal definition:","bold":true},{"text":" the relation between persons who have agreed to share the profits of a business carried on by all or any of them acting for all."}]},{"text":[{"text":"The law does "},{"text":"not","bold":true},{"text":" require a written partnership agreement to form a partnership (it may be oral or implied by conduct). An ordinary partnership usually has "},{"text":"2 to 20 partners","bold":true},{"text":"; professional firms such as lawyers and accountants may be larger."}]},{"text":[{"text":"Partnership agreement (deed):","bold":true},{"text":" sets out "},{"text":"how profits and losses are shared","bold":true},{"text":", capital contributions, interest on capital and drawings, partners' salaries, rights and duties, admission and retirement of partners, and settling disputes."}]},{"text":[{"text":"Where there is no agreement","bold":true},{"text":", the usual rules are: profits and losses are shared "},{"text":"equally","bold":true},{"text":"; no interest on capital; no salary for any partner; interest at 5% a year on a partner's loan to the firm (over and above agreed capital)."}]}]},{"type":"paragraph","text":[{"text":"4 types of partnerships (business alliances):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Strategic alliances between non-competitors"}]},{"text":[{"text":"Strategic partnerships between competitors (called "},{"text":"coopetition","bold":true},{"text":")"}]},{"text":[{"text":"Joint ventures to develop new business"}]},{"text":[{"text":"Buyer-supplier relationships to assure reliable supplies"}]}]},{"type":"paragraph","text":[{"text":"8 types of partners:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Active or managing partner:","bold":true},{"text":" takes part in the firm's management."}]},{"text":[{"text":"Inactive or sleeping (dormant) partner:","bold":true},{"text":" contributes capital and shares profit but does not manage."}]},{"text":[{"text":"Nominal partner:","bold":true},{"text":" lends only his name, yet is liable to outsiders."}]},{"text":[{"text":"Partner by estoppel or holding out:","bold":true},{"text":" lets himself be presented as a partner, so is liable to those who relied on it."}]},{"text":[{"text":"Partner in profits only:","bold":true},{"text":" shares profits but not losses."}]},{"text":[{"text":"Minor as a partner:","bold":true},{"text":" admitted to the benefits only; not personally liable for losses."}]},{"text":[{"text":"Secret partner:","bold":true},{"text":" active, but hidden from the public."}]},{"text":[{"text":"Sub-partner:","bold":true},{"text":" an outsider sharing one partner's profit share; no rights against the firm."}]}]},{"type":"paragraph","text":[{"text":"7 advantages:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Bridging the gap in expertise and knowledge"}]},{"text":[{"text":"Additional capital"}]},{"text":[{"text":"Cost savings"}]},{"text":[{"text":"More business opportunities"}]},{"text":[{"text":"Responsibilities can be shared"}]},{"text":[{"text":"Emotional support"}]},{"text":[{"text":"New perspective"}]}]},{"type":"paragraph","text":[{"text":"8 disadvantages:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Potential liabilities"}]},{"text":[{"text":"Loss of autonomy"}]},{"text":[{"text":"Emotional issues"}]},{"text":[{"text":"Conflict and disagreements"}]},{"text":[{"text":"Future selling complications"}]},{"text":[{"text":"Lack of stability"}]},{"text":[{"text":"Higher taxes"}]},{"text":[{"text":"Splitting profits"}]}]},{"type":"paragraph","text":[{"text":"Sources of funds:","bold":true},{"text":" partners' capital contributions; admitting a new partner; partners' loans; ploughed-back profits; bank loans and overdrafts; suppliers' credit; equipment leasing; hire purchase. "},{"text":"Not","bold":true},{"text":" issue of shares."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Unlimited personal liability","bold":true},{"text":" (\"potential liabilities\") is the main disadvantage of an ordinary partnership: each partner is liable for all the firm's debts, even those caused by another partner."}]},{"text":[{"text":"Pooled skills and resources","bold":true},{"text":" is the main advantage."}]},{"text":[{"text":"Decision-making is distributed (shared) among partners.","bold":true},{"text":" Control by one person describes a sole proprietor; voting by equity holders $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin101', 28, $study_guide$describes a company."}]},{"text":[{"text":"Lack of stability:","bold":true},{"text":" death, retirement or bankruptcy of a partner dissolves an ordinary partnership unless the agreement says otherwise."}]},{"text":[{"text":"Trap:","bold":true},{"text":" a partnership "},{"text":"cannot issue shares","bold":true},{"text":", because only companies have share capital. Suppliers' credit, leasing and hire purchase are all open to it."}]},{"text":[{"text":"CAMA 2020","bold":true},{"text":" (Companies and Allied Matters Act 2020) also allows a "},{"text":"Limited Liability Partnership (LLP)","bold":true},{"text":" and a "},{"text":"Limited Partnership (LP)","bold":true},{"text":", registered with the CAC. In an LP at least one general partner keeps unlimited liability."}]}]},{"type":"paragraph","text":[{"text":"Worked example (sharing profit):","bold":true},{"text":" Ade (capital ₦6,000,000) and Ngozi (capital ₦4,000,000) make a profit of ₦3,000,000."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"(a) Agreement: share in capital ratio 6:4 = 3:2. Ade = 3/5 × 3,000,000 = "},{"text":"₦1,800,000","bold":true},{"text":"; Ngozi = 2/5 × 3,000,000 = "},{"text":"₦1,200,000","bold":true},{"text":"."}]},{"text":[{"text":"(b) Agreement: 10% interest on capital, Ngozi gets a salary of ₦400,000, remainder shared equally. Interest: Ade ₦600,000, Ngozi ₦400,000. Remainder = 3,000,000 − 600,000 − 400,000 − 400,000 = ₦1,600,000, so ₦800,000 each. Ade = "},{"text":"₦1,400,000","bold":true},{"text":"; Ngozi = 400,000 + 400,000 + 800,000 = "},{"text":"₦1,600,000","bold":true},{"text":" (total ₦3,000,000)."}]},{"text":[{"text":"(c) No agreement: equal shares, no interest or salary: "},{"text":"₦1,500,000 each","bold":true},{"text":"."}]}]}]},{"number":"7.3","title":"The limited liability company (private and public)","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Limited company:","bold":true},{"text":" a general form of incorporation that "},{"text":"limits the amount of liability","bold":true},{"text":" undertaken by the company's shareholders. It is a legal structure that ensures the liability of members or subscribers is "},{"text":"limited to their stake","bold":true},{"text":" in the company (their investments or commitments)."}]},{"text":[{"text":"Limited liability company (LLC):","bold":true},{"text":" a business structure where owners are "},{"text":"not held personally liable","bold":true},{"text":" for the debts or other liabilities the business may incur."}]},{"text":[{"text":"Corporation / company:","bold":true},{"text":" a "},{"text":"distinct (separate) legal entity","bold":true},{"text":" from its owners; it can own property, sue and be sued in its own name. It is "},{"text":"owned by shareholders","bold":true},{"text":", each holding a stake."}]},{"text":[{"text":"Features of the corporate form:","bold":true},{"text":" separate legal entity; limited liability; "},{"text":"perpetual succession","bold":true},{"text":" (it continues when owners die or sell); transferable shares; separation of ownership (shareholders) from control (directors); raises capital by "},{"text":"issuing equity shares","bold":true},{"text":" and debentures."}]}]},{"type":"paragraph","text":[{"text":"2 types (by number of members):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Single-member LLC:","bold":true},{"text":" operates like a sole proprietorship but with the protection of the law on the liability of the business."}]},{"text":[{"text":"Multi-member LLC:","bold":true},{"text":" two or more members form and own the business."}]}]},{"type":"paragraph","text":[{"text":"LLC vs other forms:","bold":true}]},{"type":"table","header":[[{"text":"Point"}],[{"text":"Enterprise / sole proprietor"}],[{"text":"Company (LLC)"}]],"rows":[[[{"text":"Legal entity"}],[{"text":"Not separate from owner"}],[{"text":"Separate legal entity"}]],[[{"text":"Liability"}],[{"text":"Owner personally liable for all debts"}],[{"text":"Members not personally liable (limited)"}]],[[{"text":"Owners"}],[{"text":"Always one person (sole proprietor)"}],[{"text":"One or more members"}]]]},{"type":"paragraph","text":[{"text":"6 advantages of LLC:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Limited personal liability for the company's business debts."}]},{"text":[{"text":"Fairly easy to organise and get running."}]},{"text":[{"text":"Many business expenses can be written off as deductions, lowering taxable income."}]},{"text":[{"text":"Can be run by its members, or members can hire a manager for day-to-day affairs; members choose how involved to be."}]},{"text":[{"text":"The LLC designation lends greater credibility to a sole proprietorship or partnership."}]},{"text":[{"text":"Less record-keeping than corporations, so more focus on business goals."}]}]},{"type":"paragraph","text":[{"text":"4 disadvantages of LLC:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Depending on state law, it may have to be dissolved on the death or bankruptcy of a member (a corporation can exist in perpetuity)."}]},{"text":[{"text":"Under pass-through taxation, members pay self-employment taxes on top of personal income tax."}]},{"text":[{"text":"Unless the Operating Agreement is properly conceived, executed and understood, roles and responsibilities may be unclear."}]},{"text":[{"text":"Penalties, stated in the Operating Agreement, for failing to make capital contributions."}]}]},{"type":"paragraph","text":[{"text":"Private vs public company:","bold":true}]},{"type":"table","header":[[{"text":"Point"}],[{"text":"Private company (Ltd)"}],[{"text":"Public company (Plc)"}]],"rows":[[[{"text":"Name ends in"}],[{"text":"\"Limited\" (Ltd)"}],[{"text":"\"Public Limited Company\" (Plc)"}]],[[{"text":"Members"}],[{"text":"One person upwards; at most 50 (excluding employees)"}],[{"text":"No maximum"}]],[[{"text":"Offer of shares"}],[{"text":"Can$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin101', 29, $study_guide$not invite the public to buy its shares"}],[{"text":"Can offer shares to the public"}]],[[{"text":"Share transfer"}],[{"text":"Restricted by its articles"}],[{"text":"Freely transferable; may be listed on the NGX"}]],[[{"text":"Regulation"}],[{"text":"Less"}],[{"text":"Heavier: SEC rules, published accounts"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Limited liability is the "},{"text":"advantage","bold":true},{"text":" that exam options call \"limited owner liability\" or \"limited liability for investors\": a shareholder loses at most what he paid, or still owes, for his shares. If Bisi's shop (Lesson 7.1) had been Bisi Stores Ltd, the ₦3,000,000 shortfall would fall on creditors, not on Bisi's house."}]},{"text":[{"text":"Double taxation","bold":true},{"text":" is the classic disadvantage of a corporation: profit is taxed once as company income tax and again when dividends are taxed in shareholders' hands. "},{"text":"Worked example (illustrative rates):","bold":true},{"text":" profit ₦10,000,000; company tax at 30% = ₦3,000,000; profit after tax ₦7,000,000 paid as dividend; withholding tax at 10% = ₦700,000; shareholders receive ₦6,300,000. Total tax = 3,000,000 + 700,000 = ₦3,700,000, which is "},{"text":"37%","bold":true},{"text":" of the original profit."}]},{"text":[{"text":"Other corporate disadvantages: complex, costly formation; heavy regulation; agency conflict."}]},{"text":[{"text":"Nigeria:","bold":true},{"text":" companies are formed under "},{"text":"CAMA 2020","bold":true},{"text":" by registering with the "},{"text":"CAC","bold":true},{"text":". CAMA 2020 lets "},{"text":"one person","bold":true},{"text":" form a private company. Companies may be limited by shares, limited by guarantee (often non-profit bodies) or unlimited."}]},{"text":[{"text":"The LLC disadvantages use United States terms (\"state law\", \"Operating Agreement\"); learn them as listed. The Nigerian counterpart of the Operating Agreement is the articles of association."}]},{"text":[{"text":"Trap:","bold":true},{"text":" only "},{"text":"public","bold":true},{"text":" companies can trade shares on a public market. \"Public market trading\" is not a feature of every LLC."}]}]}]},{"number":"7.4","title":"Public corporations and cooperatives","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Public corporation:","bold":true},{"text":" a corporation "},{"text":"owned and operated by a government","bold":true},{"text":", established for the administration of certain public programmes. It is set up by an "},{"text":"act of parliament","bold":true},{"text":" (in Nigeria, the National Assembly or a state House of Assembly), owned and managed by government to provide "},{"text":"essential services to the public at affordable cost","bold":true},{"text":". Also called a public enterprise or statutory corporation."}]}]},{"type":"paragraph","text":[{"text":"2 types of public corporation:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Those providing "},{"text":"essential services","bold":true},{"text":": water corporations, the National Electric Power Authority (NEPA), Federal Housing Authority."}]},{"text":[{"text":"Those of a "},{"text":"commercial nature","bold":true},{"text":": state-owned banks, hotels, textile mills, transport services."}]}]},{"type":"paragraph","text":[{"text":"Public corporation vs public company:","bold":true},{"text":" a "},{"text":"public corporation","bold":true},{"text":" is owned and controlled by "},{"text":"government","bold":true},{"text":" and provides essential services. A "},{"text":"public limited company","bold":true},{"text":" is a "},{"text":"privately owned","bold":true},{"text":" business that "},{"text":"offers shares to the public","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"8 examples of public enterprises in Nigeria:","bold":true},{"text":" Nigerian Railway Corporation (NRC); Central Bank of Nigeria (CBN); water corporations across the country; Nigerian Postal Service; Defence Industries Corporation of Nigeria; National Universities Commission (NUC); NAFDAC; NDLEA."}]},{"type":"paragraph","text":[{"text":"4 advantages:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Flexibility and independence retained"}]},{"text":[{"text":"Governmental review promotes public interest"}]},{"text":[{"text":"Recruitment power"}]},{"text":[{"text":"Debt shared by more investors"}]}]},{"type":"paragraph","text":[{"text":"4 disadvantages:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Complex legal requirements"}]},{"text":[{"text":"Increased governmental oversight"}]},{"text":[{"text":"Many company records are public"}]},{"text":[{"text":"Ownership and management are split"}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Cooperative society:","bold":true},{"text":" a business "},{"text":"owned and controlled by its members","bold":true},{"text":", formed voluntarily to "},{"text":"serve the needs of its member-owners","bold":true},{"text":", not to maximise profit for outside shareholders."}]},{"text":[{"text":"Principles:","bold":true},{"text":" voluntary and open membership; "},{"text":"democratic control (one member, one vote","bold":true},{"text":", however many shares held); members contribute capital and share any surplus; autonomy; education and training of members; cooperation among cooperatives; concern for the community."}]},{"text":[{"text":"Types:","bold":true},{"text":" consumer (retail); producer and agricultural; marketing; "},{"text":"credit and thrift","bold":true},{"text":" (savings and loans); housing; multipurpose."}]},{"text":[{"text":"Sources of funds:","bold":true},{"text":" members' shares, entrance fees and savings; retained surplus; loans; grants."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A public corporation keeps flexibility beca$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin101', 30, $study_guide$use it is a "},{"text":"separate legal body","bold":true},{"text":" with its own board, while government review keeps it serving the public. \"Ownership and management split\": government owns it, a board runs it."}]},{"text":[{"text":"Sources of funds for public corporations:","bold":true},{"text":" government grants, subventions and budget allocations; government loans; internally generated revenue (fees and charges); bonds; local and foreign loans, often guaranteed by government."}]},{"text":[{"text":"Trap:","bold":true},{"text":" \"public\" in "},{"text":"public corporation","bold":true},{"text":" means government-owned; \"public\" in "},{"text":"public limited company","bold":true},{"text":" means its shares are offered to the public. Dangote Cement Plc is a public company, not a public corporation."}]},{"text":[{"text":"Many public enterprises have since been privatised; NEPA was unbundled into separate electricity companies."}]},{"text":[{"text":"Cooperative surplus","bold":true},{"text":" is usually returned as a "},{"text":"patronage dividend","bold":true},{"text":", in proportion to each member's dealings with the society, and interest on members' capital is limited. "},{"text":"Worked example:","bold":true},{"text":" a consumer cooperative earns a surplus of ₦1,200,000; members bought goods worth ₦24,000,000 from it. Rate = 1,200,000 / 24,000,000 = "},{"text":"5 kobo per naira (5%)","bold":true},{"text":". Mrs Okon bought ₦600,000, so she receives 600,000 × 0.05 = "},{"text":"₦30,000","bold":true},{"text":"."}]},{"text":[{"text":"A staff cooperative that takes monthly savings and gives members cheap loans is a credit and thrift cooperative. Liability is "},{"text":"not","bold":true},{"text":" what defines a cooperative; serving its members is."}]}]}]},{"number":"7.5","title":"Choosing a form of business","mustKnow":[{"type":"paragraph","text":[{"text":"Factors to consider in choosing a form:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Capital required","bold":true},{"text":" and ease of raising it (shares are open only to companies; a public offer only to a Plc)"}]},{"text":[{"text":"Liability","bold":true},{"text":" of owners (limited or unlimited)"}]},{"text":[{"text":"Control","bold":true},{"text":" and management (how much the owner wants to keep)"}]},{"text":[{"text":"Ease and cost of formation","bold":true},{"text":" and legal formalities"}]},{"text":[{"text":"Continuity","bold":true},{"text":" (perpetual succession or ending with the owner)"}]},{"text":[{"text":"Taxation","bold":true},{"text":" (personal income tax, or company tax plus tax on dividends)"}]},{"text":[{"text":"Nature and size","bold":true},{"text":" of the business and its risk"}]},{"text":[{"text":"Profit sharing","bold":true},{"text":" (kept by one owner or split)"}]},{"text":[{"text":"Privacy","bold":true},{"text":" (how much must be disclosed publicly)"}]},{"text":[{"text":"Government regulation","bold":true}]},{"text":[{"text":"Transferability","bold":true},{"text":" of ownership interest"}]}]},{"type":"paragraph","text":[{"text":"Comparison:","bold":true}]},{"type":"table","header":[[{"text":"Point"}],[{"text":"Sole proprietor"}],[{"text":"Partnership"}],[{"text":"Company"}],[{"text":"Cooperative"}],[{"text":"Public corporation"}]],"rows":[[[{"text":"Owners"}],[{"text":"One"}],[{"text":"2 or more partners"}],[{"text":"Shareholders"}],[{"text":"Members"}],[{"text":"Government"}]],[[{"text":"Liability"}],[{"text":"Unlimited"}],[{"text":"Unlimited (ordinary)"}],[{"text":"Limited"}],[{"text":"Usually limited"}],[{"text":"Government bears"}]],[[{"text":"Legal entity"}],[{"text":"No"}],[{"text":"No (ordinary)"}],[{"text":"Yes"}],[{"text":"Yes, once registered"}],[{"text":"Yes"}]],[[{"text":"Continuity"}],[{"text":"Ends with owner"}],[{"text":"Unstable"}],[{"text":"Perpetual"}],[{"text":"Continues"}],[{"text":"Perpetual"}]],[[{"text":"Main aim"}],[{"text":"Profit"}],[{"text":"Profit"}],[{"text":"Profit"}],[{"text":"Serve members"}],[{"text":"Public service"}]],[[{"text":"Raises funds by"}],[{"text":"Savings, loans"}],[{"text":"Partners' capital, loans"}],[{"text":"Shares, debentures, loans"}],[{"text":"Members' shares, savings"}],[{"text":"Government funds, bonds"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Match form to need: a small barbing salon suits a sole proprietorship; professionals sharing skills, a partnership; a manufacturer needing billions of naira, a public company selling shares on the NGX; market women wanting cheap loans, a cooperative; essential services, a public corporation."}]},{"text":[{"text":"Trap:","bold":true},{"text":" the forms of business ownership are sole proprietorship, partnership, company (corporation), cooperative and public enterprise. Financial contracts such as an "},{"text":"interest rate swap","bold":true},{"text":" (exchanging interest payments), a bond or a lease are "},{"text":"not","bold":true},{"text":" forms of business ownership."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Sole proprietor: one owner, unlimited liability, total control, easy to form, ends when the owner dies or closes it."}]},{"text":[{"text":"Partnership: 2 or more share profits and losses; no written agreement needed; no agreement = share equally; pooled skills but unlimited liability; cannot issue shares."}]},{"text":[{"text":"8 partners: active, sleeping, nominal, estoppel, profits only, minor, secret, sub-partner."}]},{"text":[{"text":"Company: separate legal entity owned by shareholders, limited liability, perpetual succession, raises capital by issuing shares; double taxation is its classic drawback."}]},{"text":[{"text":"Private (Ltd) cannot offer shares to the public; public (Plc) can and may list on the NGX. In Nigeria, CAMA 2020 and the CAC."}]},{"text":[{"text":"Public corporation: government-owned by statute for essential services; two types, essential and commercial; not the s$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin101', 31, $study_guide$ame as a public company."}]},{"text":[{"text":"Cooperative: owned and controlled by members to serve members; one member, one vote; surplus shared by patronage."}]},{"text":[{"text":"Choose by capital, liability, control, formation cost, continuity, tax, size, privacy, regulation."}]}]}],"theory":{"itemId":"284bd3a0-7fda-51d7-a7e6-2dcf4eab1916","question":[{"type":"paragraph","text":[{"text":"Tunde and Amaka are partners with capitals of ₦5,000,000 and ₦3,000,000. Profit for the year is ₦2,400,000. (a) The deed allows 5% interest on capital and shares the remainder 3:1. Find each partner's share. (b) What would each get if there were no partnership agreement?"}]}]},"practice":[{"topic":"Forms of Business Firm","named":false}]}}],"theory":[{"kind":"theory_question","itemId":"b463c843-3c57-55e1-97b1-e602e2108f20","sourceKey":"guide-theory:1","position":1,"payload":{"prompt":"Zenith Agro plc earns profit after tax of ₦80,000,000 and pays a dividend of 25%. (a) How much is retained? (b) Which finance decision is this, and what is its other name?"},"answer":{"kind":"model_answer","itemId":"4021c226-7a18-5905-91cd-3c0817fa9d5c","sourceKey":"guide-answer:1","payload":{"body":"(a) Dividend = 25% × ₦80,000,000 = ₦20,000,000. Retained = ₦80,000,000 − ₦20,000,000 = ₦60,000,000. (b) It is the dividend decision, also called the profit allocation decision: choosing how much profit to pay out and how much to keep, with the aim of maximising shareholders' wealth."}}},{"kind":"theory_question","itemId":"1df01bce-1f01-5a69-a6a6-1c45816fa063","sourceKey":"guide-theory:2","position":2,"payload":{"prompt":"A firm can invest ₦700,000 today in a project that returns ₦300,000 at the end of each of the next 3 years. The required return is 10%. (a) What is the accounting profit? (b) What is the NPV? (c) Does the project increase shareholders' wealth?"},"answer":{"kind":"model_answer","itemId":"7d7a7f51-52e1-5023-94a6-49919fce8b6c","sourceKey":"guide-answer:2","payload":{"body":"• (a) Profit = 3 × 300,000 − 700,000 = ₦200,000.\n• (b) PV year 1 = 300,000 / 1.1 = ₦272,727.27; year 2 = 300,000 / 1.1^2 = ₦247,933.88; year 3 = 300,000 / 1.1^3 = ₦225,394.44. Total PV = ₦746,055.60. NPV = 746,055.60 − 700,000 = ₦46,055.60 (rounded to the nearest kobo).\n• (c) Yes. NPV is positive, so the project adds about ₦46,056 of value for shareholders. Note that the wealth gain is smaller than the ₦200,000 profit, because NPV allows for the time value of money and profit does not."}}},{"kind":"theory_question","itemId":"8d2a2b51-0d6b-55e6-8a93-ea787c2b13d8","sourceKey":"guide-theory:3","position":3,"payload":{"prompt":"A project's cash flows and probabilities are ₦10,000 (0.2), ₦15,000 (0.3), ₦20,000 (0.4) and ₦30,000 (0.1). Calculate the expected value, variance, standard deviation and coefficient of variation."},"answer":{"kind":"model_answer","itemId":"89eb1599-dab4-5854-9f7b-6ec59a31583b","sourceKey":"guide-answer:3","payload":{"body":"R | P | P × R | R − ER | (R − ER)^2 | P × (R − ER)^2\n10,000 | 0.2 | 2,000 | −7,500 | 56,250,000 | 11,250,000\n15,000 | 0.3 | 4,500 | −2,500 | 6,250,000 | 1,875,000\n20,000 | 0.4 | 8,000 | 2,500 | 6,250,000 | 2,500,000\n30,000 | 0.1 | 3,000 | 12,500 | 156,250,000 | 15,625,000\nTotal | 1.0 | 17,500 |  |  | 31,250,000\n• Expected value = ₦17,500\n• Variance = 31,250,000\n• SD = square root of 31,250,000 = ₦5,590.17\n• CV = 5,590.17 / 17,500 × 100 = 31.94%, about 32%"}}},{"kind":"theory_question","itemId":"3a6f4bbb-2379-5802-a128-1abedf801b3c","sourceKey":"guide-theory:4","position":4,"payload":{"prompt":"Unilag Ventures deposits ₦150,000 at the end of each year for 4 years at 15% per annum. How much will be in the fund at the end of year 4, and how much if each deposit were made at the beginning of the year?"},"answer":{"kind":"model_answer","itemId":"dad68fa3-6efb-5445-a66d-53778b291e19","sourceKey":"guide-answer:4","payload":{"body":"Ordinary annuity: FV = 150,000 × (1.15^4 - 1) ÷ 0.15 = 150,000 × (1.74901 - 1) ÷ 0.15 = 150,000 × 4.99337 = ₦749,006.25. Annuity due: 749,006.25 × 1.15 = ₦861,357.19."}}},{"kind":"theory_question","itemId":"58b6d20d-4ef2-5fc4-b6eb-9cbf882aaaa7","sourceKey":"guide-theory:5","position":5,"payload":{"prompt":"Bode Plc earned profit after tax of ₦4,800,000 and paid a preference dividend of ₦800,000 and an ordinary dividend of ₦1,600,000. It has 10,000,000 ordinary shares priced at ₦4.00 each. Calculate EPS, DPS, dividend cover, P/E ratio and dividend yield."},"answer":{"kind":"model_answer","itemId":"d88239ef-6037-5373-b7cc-c83d5a5d8e61","sourceKey":"guide-answer:5","payload":{"body":"Earnings for ordinary shareholders = 4,800,000 - 800,000 = ₦4,000,000. EPS = 4,000,000 ÷ 10,000,000 = ₦0.40. DPS = 1,600,000 ÷ 10,000,000 = ₦0.16. Dividend cover = 4,000,000 ÷ 1,600,000 = 2.5 times. P/E = 4.00 ÷ 0.40 = 10 times. Dividend yield = 0.16 ÷ 4.00 × 100 = 4%."}}},{"kind":"theory_question","itemId":"f744b4e0-a23a-576b-aef7-06a24f544785","sourceKey":"guide-theory:6","position":6,"payload":{"prompt":"A supplier invoices ₦500,000 on terms of 2% discount if paid within 10 days, otherwise full payment in 30 days. What is the approximate annual cost of using the trade credit (giving up the discount)?"},"answer":{"kind":"model_answer","itemId":"c760b622-a5c5-5bef-9b54-bc35a7bcafc9","sourceKey":"guide-answer:6","payload":{"body":"• Pay on day 10: 500,000 × 0.98 = ₦490,000. Pay on day 30: ₦500,000.\n• Giving up the discount costs ₦10,000 for the use of ₦490,000 for 20 extra days.\n• Annual cost = (10,000 / 490,000) × (365 / 20) = 37.24% (to 2 d.p.). Trade credit is \"free\" only within the discount period; after that it can be dearer than a bank overdraft."}}},{"kind":"theory_question","itemId":"284bd3a0-7fda-51d7-a7e6-2dcf4eab1916","sourceKey":"guide-theory:7","position":7,"payload":{"prompt":"Tunde and Amaka are partners with capitals of ₦5,000,000 and ₦3,000,000. Profit for the year is ₦2,400,000. (a) The deed allows 5% interest on capital and shares the remainder 3:1. Find each partner's$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_fin101', 32, $study_guide$ share. (b) What would each get if there were no partnership agreement?"},"answer":{"kind":"model_answer","itemId":"5b61c735-6363-52fa-9e65-2b294d517389","sourceKey":"guide-answer:7","payload":{"body":"• (a) Interest: Tunde 5% × 5,000,000 = ₦250,000; Amaka 5% × 3,000,000 = ₦150,000. Remainder = 2,400,000 − 250,000 − 150,000 = ₦2,000,000. Tunde 3/4 × 2,000,000 = ₦1,500,000; Amaka 1/4 × 2,000,000 = ₦500,000. Totals: Tunde = ₦1,750,000; Amaka = ₦650,000 (check: ₦2,400,000).\n• (b) No agreement: no interest on capital, profit shared equally: 2,400,000 / 2 = ₦1,200,000 each."}}}]}$study_guide$);
